#!/usr/bin/env python3
"""B3-02 空白行业填充生成器：表达式驱动批量生成 A 级工具。"""
import os, re, math

ROOT = os.path.dirname(os.path.abspath(__file__))
TOOLS_DIR = os.path.join(ROOT, 'tools')

def esc(s):
    return s.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;')

HTML_TPL = '''<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
<meta name="toolbox" content="cat={cat},industry={industry},icon={icon},bg={bg}">
<title>{title} - ToolBox</title>
<link rel="canonical" href="https://chenguangwu.github.io/tools/{industry}/{filename}">
<meta property="og:title" content="{title} - ToolBox">
<meta property="og:description" content="{desc}">
<meta property="og:type" content="website">
<meta property="og:url" content="https://chenguangwu.github.io/tools/{industry}/{filename}">
<meta property="og:image" content="https://chenguangwu.github.io/og-image.png">
<meta name="twitter:card" content="summary">
<meta name="twitter:title" content="{title} - ToolBox">
<meta name="twitter:description" content="{desc}">
<meta name="twitter:image" content="https://chenguangwu.github.io/og-image.png">
<link rel="stylesheet" href="../../css/common.css">
<script src="../../js/common.js"></script>
</head>
<body>
<div class="nav">
  <a href="../../index.html">← ToolBox</a>
  <span>/ {title}</span>
  <button class="theme-btn" onclick="ToolBox.toggleToolTheme()">🌙</button>
</div>
<div class="container">
  <div class="card">
    <h2>{icon} {title}</h2>
    <p style="font-size:13px;color:var(--text-muted);margin-bottom:16px;">{desc}</p>
{inputs}
    <div class="toolbar">
      <button class="btn primary" onclick="calc()">计算</button>
      <button class="btn" onclick="copyResult()">复制结果</button>
    </div>
    <div class="result-box" id="result" data-viz="{viz_type}" data-viz-max="{viz_max}" data-viz-min="{viz_min}"></div>
  </div>
  <div class="card formula-box">
    <h3>📐 计算公式与说明</h3>
    <div class="formula-eq">{formula_html}</div>
    <p style="font-size:13px;color:var(--text-muted);margin-top:12px;">{formula_note}</p>
  </div>
</div>
<script>
{script}
function copyResult() {{
  const txt = document.getElementById('result').innerText;
  if (!txt) return;
  navigator.clipboard.writeText(txt).then(() => ToolBox.toast && ToolBox.toast('已复制结果')).catch(() => {{
    const ta = document.createElement('textarea'); ta.value = txt; document.body.appendChild(ta);
    ta.select(); document.execCommand('copy'); document.body.removeChild(ta);
  }});
}}
calc();
</script>
</body>
</html>
'''

def build_expr_tool(spec):
    ind, cat, title, icon, bg, desc = spec['ind'], spec['cat'], spec['title'], spec['icon'], spec['bg'], spec['desc']
    inputs = spec['inputs']
    results = spec['results']
    formula_html = spec['formula']
    note = spec['note']
    viz = spec.get('viz', ('bar', 0, 100))
    fn = _make_fn(ind, title, spec.get('file'))

    # inputs HTML
    inp_html = '\n'.join(f'    <div class="input-row"><label>{i[1]}</label><input type="number" id="{i[0]}" value="{i[2]}" step="{i[3]}" oninput="calc()"></div>' for i in inputs)

    # script: read inputs then compute results
    lines = ['function calc(){']
    for i in inputs:
        lines.append(f"  const {i[0]} = +document.getElementById('{i[0]}').value || 0;")
    lines.append('  let html = \'\';')
    for r in results:
        label, expr, unit, dec = r
        expr_js = expr.replace('^', '**')
        lines.append(f"  const __v = ({expr_js});")
        lines.append(f"  html += `<p>{label}：<strong style=\"font-size:18px;color:var(--primary);\">${{__v.toFixed({dec})}}</strong> {unit}</p>`;")
    lines.append("  document.getElementById('result').innerHTML = html;")
    lines.append('}')
    script = '\n'.join(lines)

    html = HTML_TPL.format(
        cat=cat, industry=ind, icon=icon, bg=bg, title=esc(title), desc=esc(desc),
        filename=fn, inputs=inp_html, script=script,
        formula_html=formula_html, formula_note=esc(note),
        viz_type=viz[0], viz_min=viz[1], viz_max=viz[2]
    )
    path = os.path.join(TOOLS_DIR, ind, fn)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(html)
    return path

# 存储所有生成文件
GEN = []

# 跟踪已用文件名，避免中文标题 slug 为空/重复导致互相覆盖
_USED = set()
def _make_fn(ind, title, explicit):
    if explicit:
        return explicit if explicit.endswith('.html') else explicit + '.html'
    s = re.sub(r'[^a-z0-9]+', '-', title.lower()).strip('-') or ind
    base = s
    i = 2
    cand = base + '.html'
    while cand in _USED:
        cand = f"{base}-{i}.html"
        i += 1
    _USED.add(cand)
    return cand

def add(spec):
    GEN.append(build_expr_tool(spec))

