add({'ind':'statistics','cat':'math','title':'置信区间估算','icon':'🎯','bg':'#f0f9ff','desc':'根据样本均值、标准差和样本量计算总体均值的置信区间。','inputs':[('xbar','样本均值',50,'any'),('s','样本标准差',5,'any'),('n','样本量',30,'1'),('cl','置信水平 %',95,'any')],'results':[('下限','xbar - (Math.abs(Math.SQRT2*(()=>{let a=0.147,x=(1-cl/100)/2;let a1=Math.log(1-x*x),a2=(2/(Math.PI*a)+a1/2),a3=a1/a;return x*Math.sqrt(-a2+Math.sqrt(a2*a2-a3));})())*s/Math.sqrt(n))','',4),('上限','xbar + (Math.abs(Math.SQRT2*(()=>{let a=0.147,x=(1-cl/100)/2;let a1=Math.log(1-x*x),a2=(2/(Math.PI*a)+a1/2),a3=a1/a;return x*Math.sqrt(-a2+Math.sqrt(a2*a2-a3));})())*s/Math.sqrt(n))','',4)],'formula':'CI = x̄ ± Z₁₋α/₂ · s / √n','note':'大样本或已知总体标准差时使用 Z 分布。','viz':('bar',0,100)})
