add({'ind':'statistics','cat':'math','title':'标准差与方差','icon':'📉','bg':'#f0f9ff','desc':'计算样本/总体标准差、方差、变异系数（CV）。','inputs':[('n1','数据1',10,'any'),('n2','数据2',12,'any'),('n3','数据3',14,'any'),('n4','数据4',16,'any'),('n5','数据5',18,'any'),('n6','数据6',20,'any'),('n7','数据7',22,'any'),('type','类型 1=样本 2=总体',1,'1')],'results':[('方差','(()=>{const arr=[n1,n2,n3,n4,n5,n6,n7],n=7,mean=arr.reduce((a,b)=>a+b,0)/n;return arr.reduce((a,b)=>a+Math.pow(b-mean,2),0)/(type===1?6:7);})()','',4),('标准差','Math.sqrt((()=>{const arr=[n1,n2,n3,n4,n5,n6,n7],n=7,mean=arr.reduce((a,b)=>a+b,0)/n;return arr.reduce((a,b)=>a+Math.pow(b-mean,2),0)/(type===1?6:7);})())','',4),('变异系数 CV','(()=>{const arr=[n1,n2,n3,n4,n5,n6,n7],n=7,mean=arr.reduce((a,b)=>a+b,0)/n;const s=Math.sqrt(arr.reduce((a,b)=>a+Math.pow(b-mean,2),0)/(type===1?6:7));return s/Math.abs(mean)*100;})()','%',2)],'formula':'方差 s² = Σ(x − x̄)² / (n − 1)（样本）或 n（总体）<br>标准差 = √方差','note':'类型填 1 为样本标准差，填 2 为总体标准差。','viz':('bar',0,50)})
add({'ind':'statistics','cat':'math','title':'百分位数计算器','icon':'🎯','bg':'#f0f9ff','desc':'输入数据集和百分位，计算第 P 百分位数。','inputs':[('d1','数据1',1,'any'),('d2','数据2',3,'any'),('d3','数据3',5,'any'),('d4','数据4',7,'any'),('d5','数据5',9,'any'),('d6','数据6',11,'any'),('d7','数据7',13,'any'),('d8','数据8',15,'any'),('d9','数据9',17,'any'),('d10','数据10',19,'any'),('p','百分位 P',75,'any')],'results':[('第 P 百分位数','(()=>{const arr=[d1,d2,d3,d4,d5,d6,d7,d8,d9,d10].sort((a,b)=>a-b);const rank=(p/100)*(arr.length-1);const l=Math.floor(rank),u=Math.ceil(rank);return l===u?arr[l]:arr[l]+(arr[u]-arr[l])*(rank-l);})()','',4)],'formula':'线性插值法：rank = P/100 × (n − 1)','note':'数据按升序排列后插值计算。','viz':('gauge',0,100)})
add({'ind':'statistics','cat':'math','title':'皮尔逊相关系数','icon':'🔗','bg':'#f0f9ff','desc':'计算两组数据的皮尔逊相关系数 r 与判定系数 R²。','inputs':[('x1','X1',1,'any'),('x2','X2',2,'any'),('x3','X3',3,'any'),('x4','X4',4,'any'),('x5','X5',5,'any'),('x6','X6',6,'any'),('y1','Y1',2,'any'),('y2','Y2',4,'any'),('y3','Y3',6,'any'),('y4','Y4',8,'any'),('y5','Y5',10,'any'),('y6','Y6',12,'any')],'results':[('皮尔逊 r','(()=>{const xs=[x1,x2,x3,x4,x5,x6],ys=[y1,y2,y3,y4,y5,y6],n=6,mx=xs.reduce((a,b)=>a+b,0)/n,my=ys.reduce((a,b)=>a+b,0)/n;let num=0,dx=0,dy=0;for(let i=0;i<n;i++){num+=(xs[i]-mx)*(ys[i]-my);dx+=Math.pow(xs[i]-mx,2);dy+=Math.pow(ys[i]-my,2);}return dx&&dy?num/Math.sqrt(dx*dy):0;})()','',4),('判定系数 R²','(()=>{const xs=[x1,x2,x3,x4,x5,x6],ys=[y1,y2,y3,y4,y5,y6],n=6,mx=xs.reduce((a,b)=>a+b,0)/n,my=ys.reduce((a,b)=>a+b,0)/n;let num=0,dx=0,dy=0;for(let i=0;i<n;i++){num+=(xs[i]-mx)*(ys[i]-my);dx+=Math.pow(xs[i]-mx,2);dy+=Math.pow(ys[i]-my,2);}const r=dx&&dy?num/Math.sqrt(dx*dy):0;return r*r;})()','',4)],'formula':'r = Σ[(x − x̄)(y − ȳ)] / √[Σ(x − x̄)² · Σ(y − ȳ)²]<br>R² = r²','note':'r 越接近 ±1 相关性越强。','viz':('gauge',-1,1)})
add({'ind':'statistics','cat':'math','title':'线性回归拟合','icon':'📏','bg':'#f0f9ff','desc':'用最小二乘法拟合 y = ax + b，输出斜率、截距与预测值。','inputs':[('x1','X1',1,'any'),('x2','X2',2,'any'),('x3','X3',3,'any'),('x4','X4',4,'any'),('x5','X5',5,'any'),('y1','Y1',2.1,'any'),('y2','Y2',4.0,'any'),('y3','Y3',6.2,'any'),('y4','Y4',7.8,'any'),('y5','Y5',10.5,'any'),('xp','预测 X',6,'any')],'results':[('斜率 a','(()=>{const xs=[x1,x2,x3,x4,x5],ys=[y1,y2,y3,y4,y5],n=5,sx=xs.reduce((a,b)=>a+b,0),sy=ys.reduce((a,b)=>a+b,0),sxx=xs.reduce((a,b)=>a+b*b,0),sxy=xs.reduce((a,b,i)=>a+xs[i]*ys[i],0);const d=n*sxx-sx*sx;return d?(n*sxy-sx*sy)/d:0;})()','',4),('截距 b','(()=>{const xs=[x1,x2,x3,x4,x5],ys=[y1,y2,y3,y4,y5],n=5,sx=xs.reduce((a,b)=>a+b,0),sy=ys.reduce((a,b)=>a+b,0),sxx=xs.reduce((a,b)=>a+b*b,0),sxy=xs.reduce((a,b,i)=>a+xs[i]*ys[i],0);const d=n*sxx-sx*sx;const a=d?(n*sxy-sx*sy)/d:0;return (sy-a*sx)/n;})()','',4),('预测 y','(()=>{const xs=[x1,x2,x3,x4,x5],ys=[y1,y2,y3,y4,y5],n=5,sx=xs.reduce((a,b)=>a+b,0),sy=ys.reduce((a,b)=>a+b,0),sxx=xs.reduce((a,b)=>a+b*b,0),sxy=xs.reduce((a,b,i)=>a+xs[i]*ys[i],0);const d=n*sxx-sx*sx;const a=d?(n*sxy-sx*sy)/d:0;const b=(sy-a*sx)/n;return a*xp+b;})()','',4)],'formula':'a = (nΣxy − ΣxΣy) / (nΣx² − (Σx)²)<br>b = (Σy − aΣx) / n','note':'输入成对数据，可指定任意 x 预测 y。','viz':('bar',0,100)})

# ==================== encode (+13 -> 15) ====================
add({'ind':'encode','cat':'encode','title':'URL 编码长度估算','icon':'🔗','bg':'#eef2ff','desc':'估算含特殊字符的字符串经 URL 编码后的长度。','inputs':[('textLen','原始字符数',20,'any'),('special','特殊字符数',5,'any'),('alreadyEnc','已编码字符数',0,'any')],'results':[('编码后长度','(textLen - special - alreadyEnc) + (special + alreadyEnc)*3','字符',0),('膨胀率','((textLen - special - alreadyEnc) + (special + alreadyEnc)*3)/Math.max(textLen,1)*100','%',1)],'formula':'URL 编码将每个非安全字符转为 %XX（3 字符）<br>编码长度 = 安全字符数 + 3 × 需编码字符数','note':'仅字母、数字及 -_.~ 为安全字符；其余均需编码。','file':'url-encoded-length.html'})
add({'ind':'encode','cat':'encode','title':'Base64 编码长度','icon':'📦','bg':'#eef2ff','desc':'计算字节数据经 Base64 编码后的字符数。','inputs':[('bytes','原始字节数',100,'any'),('padding','含填充 1/0',1,'1'),('wrap','换行字符数(0不换)',0,'any')],'results':[('编码字符数(含填充)','Math.ceil(bytes/3)*4','字符',0),('填充字符数','(3 - bytes % 3) % 3','个',0),('行数','wrap>0?Math.ceil(Math.ceil(bytes/3)*4/wrap):1','行',0)],'formula':'Base64 每 3 字节编码为 4 字符<br>字符数 = ⌈n/3⌉ × 4，末尾按余 1 补 2、余 2 补 1 个 =','note':'base64 不可缩短，仅作长度估算。','file':'base64-length.html'})
add({'ind':'encode','cat':'encode','title':'UTF-8 字节数估算','icon':'🌐','bg':'#eef2ff','desc':'按字符所属编码区估算 UTF-8 总字节数。','inputs':[('ascii','ASCII 字符数',50,'any'),('twoB','2 字节字符数',10,'any'),('threeB','3 字节字符数',5,'any'),('fourB','4 字节字符数',1,'any')],'results':[('总字节数','ascii + 2*twoB + 3*threeB + 4*fourB','字节',0),('平均字节/字符','(ascii + 2*twoB + 3*threeB + 4*fourB)/Math.max(ascii+twoB+threeB+fourB,1)','',2)],'formula':'UTF-8：ASCII 1 字节，常见汉字 3 字节，补充平面 4 字节<br>总字节 = Σ 字符数 × 该区字节数','note':'中文通常占 3 字节。','file':'utf8-bytes.html'})
add({'ind':'encode','cat':'encode','title':'信息熵（香农）','icon':'📊','bg':'#eef2ff','desc':'计算离散信源的信息熵（平均信息量）。','inputs':[('p1','事件1 概率',0.5,'any'),('p2','事件2 概率',0.25,'any'),('p3','事件3 概率',0.15,'any'),('p4','事件4 概率',0.10,'any')],'results':[('信息熵 H','(()=>{const ps=[p1,p2,p3,p4];let h=0;for(const p of ps){if(p>0)h+=-p*Math.log(p)/Math.LN2;}return h;})()','bit/符号',4)],'formula':'H = −Σ pᵢ · log₂(pᵢ)','note':'概率应之和为 1；某事件概率为 0 时该项记 0。','file':'shannon-entropy.html'})
add({'ind':'encode','cat':'encode','title':'哈夫曼平均码长','icon':'🌲','bg':'#eef2ff','desc':'根据符号频率与码长估算哈夫曼平均码长。','inputs':[('f1','符号1 频率',5,'any'),('l1','符号1 码长',1,'any'),('f2','符号2 频率',3,'any'),('l2','符号2 码长',2,'any'),('f3','符号3 频率',2,'any'),('l3','符号3 码长',3,'any')],'results':[('平均码长','(()=>{const f=[f1,f2,f3],l=[l1,l2,l3],t=f.reduce((a,b)=>a+b,0);return f.reduce((a,b,i)=>a+b*l[i],0)/t;})()','bit/符号',4),('总频数','f1+f2+f3','',0)],'formula':'平均码长 = Σ(fᵢ / Σf) · lᵢ<br>理论下界为信息熵 H','note':'输入频率（或概率，归一化后结果一致）。','file':'huffman-avg-length.html'})
add({'ind':'encode','cat':'encode','title':'校验和碰撞概率','icon':'🎯','bg':'#eef2ff','desc':'估算 n 位校验和的随机漏检概率。','inputs':[('k','校验位宽 bits',16,'any'),('attempts','尝试次数',1000,'any'),('bits','待校验数据 bits',1024,'any')],'results':[('单次漏检率','Math.pow(0.5,k)*100','%',6),('N 次后累计','(1-Math.pow(1-Math.pow(0.5,k),attempts))*100','%',6),('校验开销','k/bits*100','%',2)],'formula':'n 位校验和的随机漏检概率 ≈ 2⁻ⁿ<br>累计 ≈ 1 − (1 − 2⁻ⁿ)^N','note':'仅适用于随机错误，不能防蓄意篡改。','file':'checksum-collision.html'})
add({'ind':'encode','cat':'encode','title':'进制位数计算','icon':'🔢','bg':'#eef2ff','desc':'计算表示 N 种状态在给定进制下所需的位数。','inputs':[('N','可表示状态数',256,'any'),('base','目标进制',16,'any'),('bytes','字节容量',1,'any')],'results':[('所需位数','Math.ceil(Math.log(N)/Math.log(base))','位',0),('实际容量','Math.pow(base,Math.ceil(Math.log(N)/Math.log(base)))','',0),('可表字节数','Math.floor(Math.pow(base,Math.ceil(Math.log(N)/Math.log(base)))/8)','字节',0)],'formula':'位数 = ⌈log_base(N)⌉','note':'例如 256 种状态在 16 进制下需 2 位。','file':'radix-digits.html'})
add({'ind':'encode','cat':'encode','title':'CRC 检错能力估算','icon':'🛡️','bg':'#eef2ff','desc':'估算 CRC 对随机错误的漏检率与开销。','inputs':[('r','生成多项式阶数',16,'any'),('frames','传输帧数',10000,'any'),('dataBits','数据位宽',64,'any')],'results':[('残余错误率','Math.pow(2,-r)*100','%',8),('N 帧漏检期望','frames*Math.pow(2,-r)','帧',4),('编码开销','r/(dataBits+r)*100','%',2)],'formula':'CRC 对随机错误的漏检概率 ≈ 2⁻ʳ','note':'r 越大检错越强；常见 CRC-16(r=16)、CRC-32(r=32)。','file':'crc-error-rate.html'})
add({'ind':'encode','cat':'encode','title':'数据压缩率','icon':'🗜️','bg':'#eef2ff','desc':'计算压缩率与压缩比，评估压缩效果。','inputs':[('original','原始字节',1000,'any'),('compressed','压缩后字节',400,'any'),('files','文件数',1,'any')],'results':[('压缩率','(1-compressed/original)*100','%',2),('压缩比','original/compressed','×',2),('总节省','(original-compressed)*files','字节',0)],'formula':'压缩率 = (1 − 压缩后/原始) × 100%','note':'压缩率越接近 100% 压缩越强。','file':'compression-ratio.html'})
add({'ind':'encode','cat':'encode','title':'ASCII 可读性检测','icon':'🔤','bg':'#eef2ff','desc':'估算文本中 ASCII 与可打印字符的占比。','inputs':[('total','总字符数',100,'any'),('nonAscii','非 ASCII 数',8,'any'),('control','控制字符数',2,'any')],'results':[('ASCII 占比','(total-nonAscii)/total*100','%',1),('安全可打印占比','(total-nonAscii-control)/total*100','%',1)],'formula':'ASCII 占比 = (总数 − 非ASCII) / 总数','note':'控制字符（如换行）可视情况计入安全范围。','file':'ascii-readability.html'})
add({'ind':'encode','cat':'encode','title':'汉明码校验位','icon':'🧮','bg':'#eef2ff','desc':'计算纠正单比特错误所需汉明校验位数。','inputs':[('m','数据位数',8,'any'),('msgBits','消息数据位总数',8000,'any'),('dataRate','传输速率 bit/s',1000,'any')],'results':[('校验位数 r','(()=>{let r=0;while(Math.pow(2,r)<m+r+1)r++;return r;})()','位',0),('总码长','m+(()=>{let r=0;while(Math.pow(2,r)<m+r+1)r++;return r;})()','位',0),('编码效率','m/(m+(()=>{let r=0;while(Math.pow(2,r)<m+r+1)r++;return r;})())*100','%',1),('传输时间','(()=>{let r=0;while(Math.pow(2,r)<m+r+1)r++;return msgBits*(m+r)/(m*dataRate);})()','s',3)],'formula':'满足 2ʳ ≥ m + r + 1 的最小 r<br>码长 = m + r，效率 = m/(m+r)','note':'汉明码可检测并纠正单比特错误。','file':'hamming-bits.html'})
add({'ind':'encode','cat':'encode','title':'Base32 编码长度','icon':'🔡','bg':'#eef2ff','desc':'计算 Base32 编码字符数并与 Base64 对比。','inputs':[('bytes','原始字节数',10,'any'),('rate','传输速率 KB/s',100,'any'),('useBase64','同时用Base64 1/0',1,'1')],'results':[('Base32 字符','Math.ceil(bytes/5)*8','字符',0),('Base64 字符','Math.ceil(bytes/3)*4','字符',0),('Base32 耗时','Math.ceil(bytes/5)*8/rate','s',3)],'formula':'Base32 每 5 字节编码为 8 字符<br>字符数 = ⌈n/5⌉ × 8','note':'Base32 比 Base64 更冗长但大小写不敏感。','file':'base32-length.html'})
add({'ind':'encode','cat':'encode','title':'编码冗余度','icon':'📉','bg':'#eef2ff','desc':'比较平均码长与信息熵，评估编码冗余。','inputs':[('avgLen','平均码长',2.2,'any'),('entropy','信息熵',1.8,'any'),('symbols','符号数',1000,'any')],'results':[('冗余度','(avgLen-entropy)/avgLen*100','%',2),('编码效率','(entropy/avgLen)*100','%',2),('节省位数','symbols*(avgLen-entropy)','位',0)],'formula':'冗余 = (平均码长 − 熵) / 平均码长','note':'冗余越低编码越优，理想情况趋近 0。','file':'encoding-redundancy.html'})

# ==================== eco (+16 -> 20) ====================
add({'ind':'eco','cat':'math','title':'电力碳排放计算','icon':'⚡','bg':'#ecfdf5','desc':'根据用电量与排放因子估算 CO₂ 排放。','inputs':[('kwh','用电量 kWh',500,'any'),('factor','排放因子 kgCO₂/kWh',0.581,'any'),('days','天数',30,'any')],'results':[('CO₂ 排放','kwh*factor','kg',2),('等效树木吸收天数','kwh*factor/18.3','天',1)],'formula':'CO₂ = 用电量 × 排放因子<br>1 棵树约年吸收 18.3 kg CO₂','note':'中国电网平均因子约 0.581，绿电可低至 0。','file':'electricity-carbon.html'})
add({'ind':'eco','cat':'math','title':'日常节水量','icon':'💧','bg':'#ecfdf5','desc':'估算节水措施下的累计节水量。','inputs':[('perCapita','人均日用水 L',150,'any'),('people','人数',4,'any'),('days','天数',30,'any'),('reduce','节水比例 %',20,'any')],'results':[('节约水量','perCapita*people*days*reduce/100','L',1),('折合吨','perCapita*people*days*reduce/100/1000','吨',2)],'formula':'节约 = 人均 × 人数 × 天数 × 节水比例','note':'更换节水器具、缩短淋浴均可提升比例。','file':'water-saving.html'})
add({'ind':'eco','cat':'math','title':'燃油碳排放','icon':'🛢️','bg':'#ecfdf5','desc':'根据燃油消耗量与排放因子估算 CO₂。','inputs':[('liters','燃油量 L',100,'any'),('factor','排放因子 kgCO₂/L',2.31,'any'),('distance','行驶距离 km',1000,'any')],'results':[('CO₂ 排放','liters*factor','kg',2),('等效 km','liters*factor/0.12','km',1),('百公里排放','liters*factor/distance*100','kg/100km',2)],'formula':'CO₂ = 燃油量 × 排放因子（汽油约 2.31）','note':'柴油因子约 2.68 kgCO₂/L。','file':'fuel-carbon.html'})
add({'ind':'eco','cat':'math','title':'垃圾分类回收率','icon':'♻️','bg':'#ecfdf5','desc':'计算垃圾分类的回收率与填埋量。','inputs':[('recycled','回收量 kg',30,'any'),('total','总量 kg',100,'any'),('days','周期 天',30,'any')],'results':[('回收率','recycled/total*100','%',1),('填埋量','total-recycled','kg',1),('日均回收','recycled/days','kg/天',1)],'formula':'回收率 = 回收量 / 总量 × 100%','note':'提高回收率可显著减少填埋。','file':'recycle-rate.html'})
add({'ind':'eco','cat':'math','title':'太阳能发电量','icon':'☀️','bg':'#ecfdf5','desc':'估算光伏面板在一段时间内的发电量。','inputs':[('area','面板面积 m²',20,'any'),('eff','转换效率',0.2,'any'),('irr','日均辐照 kWh/m²',4,'any'),('days','天数',30,'any')],'results':[('发电量','area*eff*irr*days','kWh',1),('等效减排','area*eff*irr*days*0.581','kgCO₂',2)],'formula':'E = 面积 × 效率 × 日均辐照 × 天数','note':'实际受倾角、遮挡、温度影响。','file':'solar-output.html'})
add({'ind':'eco','cat':'math','title':'碳中和林面积','icon':'🌳','bg':'#ecfdf5','desc':'估算抵消年排放所需的树木与林地。','inputs':[('co2','年排放 kgCO₂',2000,'any'),('absorb','单株年吸收 kg',18.3,'any'),('treesPerHa','每公顷株数',1000,'any')],'results':[('需树木','co2/absorb','株',0),('需林地','co2/absorb/treesPerHa','公顷',3)],'formula':'树木数 = 年排放 / 单株吸收；林地 = 树木数 / 密度','note':'仅为粗略估算，未计森林碳汇衰减。','file':'carbon-forest.html'})
add({'ind':'eco','cat':'math','title':'噪音叠加计算','icon':'🔊','bg':'#ecfdf5','desc':'多个声源叠加后的总声压级。','inputs':[('L1','声源1 dB',80,'any'),('L2','声源2 dB',75,'any'),('L3','声源3 dB',70,'any')],'results':[('总声压级','10*Math.log10(Math.pow(10,L1/10)+Math.pow(10,L2/10)+Math.pow(10,L3/10))','dB',2),('比最强源增量','(10*Math.log10(Math.pow(10,L1/10)+Math.pow(10,L2/10)+Math.pow(10,L3/10)))-Math.max(L1,L2,L3)','dB',2)],'formula':'L_total = 10·log₁₀(Σ 10^(Lᵢ/10))','note':'分贝为对数单位，不可直接相加。','file':'noise-addition.html'})
add({'ind':'eco','cat':'math','title':'生态足迹估算','icon':'👣','bg':'#ecfdf5','desc':'用经验系数粗略估算人均生态足迹。','inputs':[('meat','周食肉 kg',2,'any'),('car','周驾车 km',100,'any'),('elec','月用电 kWh',200,'any'),('flights','年飞行次',2,'any')],'results':[('生态足迹','meat*52*0.0018 + car*52*0.00012 + elec*12*0.0005 + flights*0.3','gha',3)],'formula':'gha ≈ 肉食×0.0018 + 驾车×0.00012 + 用电×0.0005 + 飞行×0.3（年）','note':'全球人均生物承载力约 1.6 gha，仅供参考。','file':'ecological-footprint.html'})
add({'ind':'eco','cat':'math','title':'产品水足迹','icon':'🌊','bg':'#ecfdf5','desc':'估算常见产品的虚拟水消耗量。','inputs':[('beef','牛肉 kg',1,'any'),('shirt','棉衬衫 件',2,'any'),('coffee','咖啡 杯',3,'any')],'results':[('总耗水','beef*15415 + shirt*2700 + coffee*140','L',0),('折合 m³','(beef*15415 + shirt*2700 + coffee*140)/1000','m³',2)],'formula':'牛肉≈15415 L/kg，棉衬衫≈2700 L/件，咖啡≈140 L/杯','note':'虚拟水消耗常远高于直接用水。','file':'water-footprint.html'})
add({'ind':'eco','cat':'math','title':'甲烷温室气体当量','icon':'🐄','bg':'#ecfdf5','desc':'将甲烷排放折算为 CO₂ 当量。','inputs':[('ch4','甲烷量 kg',100,'any'),('gwp','GWP100',28,'any'),('years','时间尺度 年',100,'any')],'results':[('CO₂ 当量','ch4*gwp','kgCO₂e',1),('年均当量','ch4*gwp/years','kg/年',1)],'formula':'CO₂e = CH₄ × GWP₁₀₀（甲烷≈28）','note':'GWP100 表示 100 年尺度全球增温潜势。','file':'methane-equivalent.html'})
add({'ind':'eco','cat':'math','title':'电池储能容量','icon':'🔋','bg':'#ecfdf5','desc':'根据容量、电压与放电深度估算可用电量。','inputs':[('ah','容量 Ah',100,'any'),('v','电压 V',48,'any'),('dod','放电深度 %',80,'any')],'results':[('可用电量','ah*v/1000*dod/100','kWh',2),('总能量','ah*v/1000','kWh',2)],'formula':'E = 容量(Ah) × 电压(V) / 1000 × 放电深度','note':'DoD 越高可用容量越大但伤寿命。','file':'battery-storage.html'})
add({'ind':'eco','cat':'math','title':'风力发电估算','icon':'🌀','bg':'#ecfdf5','desc':'用风轮面积与风速估算风力机功率。','inputs':[('v','风速 m/s',8,'any'),('d','风轮直径 m',40,'any'),('cp','功率系数',0.4,'any'),('rho','空气密度',1.225,'any')],'results':[('功率','0.5*cp*rho*Math.PI*Math.pow(d/2,2)*Math.pow(v,3)/1000','kW',2)],'formula':'P = ½ · Cp · ρ · A · v³，A = π(d/2)²','note':'实际受切入/切出风速与湍流限制。','file':'wind-power.html'})
add({'ind':'eco','cat':'math','title':'雨水收集量','icon':'🌧️','bg':'#ecfdf5','desc':'根据屋顶面积与降雨量估算可收集雨水量。','inputs':[('roof','屋顶面积 m²',100,'any'),('rain','降雨量 mm',50,'any'),('eff','收集效率 %',80,'any')],'results':[('收集量','roof*rain*eff/100','L',0),('折合吨','roof*rain*eff/100/1000','吨',2)],'formula':'每 1 mm 降雨在 1 m² 上 ≈ 1 L；收集量 = 面积 × 雨量 × 效率','note':'适用于屋面雨水回收系统设计。','file':'rainwater-harvest.html'})
add({'ind':'eco','cat':'math','title':'碳汇造林投资','icon':'🌲','bg':'#ecfdf5','desc':'估算造林项目的投资与年吸收量。','inputs':[('trees','树木株数',1000,'any'),('cost','单株成本 元',30,'any'),('years','项目年限 年',20,'any')],'results':[('投资','trees*cost','元',0),('年吸收','trees*18.3','kgCO₂',0),('年投资','trees*cost/years','元/年',0)],'formula':'投资 = 株数 × 单株成本；年吸收 = 株数 × 18.3','note':'碳汇项目还需考虑养护与监测成本。','file':'afforestation-cost.html'})
add({'ind':'eco','cat':'math','title':'垃圾填埋甲烷产量','icon':'🗑️','bg':'#ecfdf5','desc':'估算填埋场有机垃圾的甲烷产量与当量。','inputs':[('organic','有机垃圾 kg/年',500,'any'),('doc','可降解碳比',0.4,'any'),('mcf','甲烷修正因子',0.8,'any'),('frac','甲烷体积比',0.5,'any')],'results':[('CH₄ 产量','organic*doc*mcf*frac*16/12','kg/年',1),('CO₂ 当量','organic*doc*mcf*frac*16/12*28','kgCO₂e',1)],'formula':'CH₄ = 有机物 × 可降解比 × MCF × 体积比 × 16/12','note':'收集的甲烷可用于发电，减少排放。','file':'landfill-methane.html'})
add({'ind':'eco','cat':'math','title':'环境影响评分','icon':'📋','bg':'#ecfdf5','desc':'对能耗、水耗、废弃物、排放综合评分。','inputs':[('energy','能耗分(0-100)',60,'any'),('water','水耗分',40,'any'),('waste','废弃物分',50,'any'),('emis','排放分',70,'any')],'results':[('综合评分','(energy+water+waste+emis)/4','分',1),('最高项','Math.max(energy,water,waste,emis)','分',0)],'formula':'综合 = (能耗 + 水耗 + 废弃物 + 排放) / 4','note':'分数越高表示环境影响越大，仅供对比。','file':'env-impact-score.html'})

# ==================== healthcare (+16 -> 20) ====================
add({'ind':'healthcare','cat':'health','title':'BMI 身体质量指数','icon':'⚖️','bg':'#fef2f2','desc':'计算 BMI 并判定体重状态（中国标准）。','inputs':[('weight','体重 kg',65,'any'),('height','身高 cm',170,'any'),('age','年龄',30,'any')],'results':[('BMI','weight/Math.pow(height/100,2)','',1),('体重状态','(()=>{const b=weight/Math.pow(height/100,2);return b<18.5?1:b<24?2:b<28?3:4;})()','等级',0)],'formula':'BMI = 体重(kg) / 身高(m)²','note':'中国标准：<18.5 偏瘦，18.5–24 正常，24–28 超重，≥28 肥胖。仅供健康参考。','file':'bmi-calculator.html'})
add({'ind':'healthcare','cat':'health','title':'BMR 基础代谢率','icon':'🔥','bg':'#fef2f2','desc':'用 Mifflin-St Jeor 公式估算基础代谢。','inputs':[('weight','体重 kg',65,'any'),('height','身高 cm',170,'any'),('age','年龄',30,'any'),('sex','性别 1男/2女',1,'1')],'results':[('BMR','10*weight + 6.25*height - 5*age + (sex===1?5:-161)','kcal/天',0)],'formula':'Mifflin-St Jeor：男 10W+6.25H−5A+5，女 −161','note':'为基础静息消耗，非每日总消耗。','file':'bmr-calculator.html'})
add({'ind':'healthcare','cat':'health','title':'体脂率估算','icon':'📐','bg':'#fef2f2','desc':'用 Deurenberg 公式估算体脂率。','inputs':[('weight','体重 kg',65,'any'),('height','身高 cm',170,'any'),('age','年龄',30,'any'),('sex','性别 1男/2女',1,'1')],'results':[('BMI','weight/Math.pow(height/100,2)','',1),('体脂率','1.2*(weight/Math.pow(height/100,2)) + 0.23*age - 10.8*(sex===1?1:0) - 5.4','%',1)],'formula':'BF% = 1.2·BMI + 0.23·年龄 − 10.8·性别(男1) − 5.4','note':'Deurenberg 公式，仅供粗略估算。','file':'body-fat-estimator.html'})
add({'ind':'healthcare','cat':'health','title':'每日饮水推荐','icon':'💧','bg':'#fef2f2','desc':'根据体重与活动/气候估算每日饮水量。','inputs':[('weight','体重 kg',65,'any'),('activity','活动系数 1-1.5',1.2,'any'),('climate','气候系数 1-1.3',1,'any')],'results':[('推荐饮水量','weight*35*activity*climate','mL',0),('折合杯数(250mL)','weight*35*activity*climate/250','杯',1)],'formula':'饮水 ≈ 体重(kg) × 35 mL × 活动 × 气候系数','note':'含食物水分，炎热/运动需增加。','file':'water-intake.html'})
add({'ind':'healthcare','cat':'health','title':'每日热量消耗 TDEE','icon':'🍎','bg':'#fef2f2','desc':'由 BMR 与活动因子估算每日总消耗。','inputs':[('bmr','基础代谢 BMR',1500,'any'),('activity','活动因子',1.5,'any'),('targetLoss','目标周减重 kg',0.5,'any')],'results':[('TDEE','bmr*activity','kcal/天',0),('减脂摄入','bmr*activity*0.8','kcal/天',0),('周需缺口','targetLoss*7700','kcal',0)],'formula':'TDEE = BMR × 活动因子（1.2 久坐–1.9 极高）','note':'减脂建议摄入低于 TDEE 约 20%。','file':'tdee-calculator.html'})
add({'ind':'healthcare','cat':'health','title':'血压分级','icon':'🩺','bg':'#fef2f2','desc':'根据收缩压/舒张压判定血压分级。','inputs':[('sys','收缩压 mmHg',120,'any'),('dia','舒张压 mmHg',80,'any'),('age','年龄',40,'any')],'results':[('脉压','sys-dia','mmHg',0),('分级','(()=>{if(sys>=180||dia>=120)return 5;if(sys>=140||dia>=90)return 4;if(sys>=130||dia>=80)return 3;if(sys>=120)return 2;return 1;})()','等级',0)],'formula':'脉压 = 收缩压 − 舒张压','note':'分级：正常<120/80，升高 120–139/80–89，1 级 140–159/90–99，2 级≥160/100。仅供参考，以医生诊断为准。','file':'blood-pressure-grade.html'})
add({'ind':'healthcare','cat':'health','title':'孕周与预产期','icon':'🤰','bg':'#fef2f2','desc':'根据末次月经估算当前孕周与预产期。','inputs':[('lmp','末次月经距今天数',100,'any'),('cycleLen','周期天数',28,'any'),('ovulationDay','排卵日(周期第几天)',14,'any')],'results':[('当前孕周','lmp/7','周',1),('距预产期','280-lmp','天',0),('距排卵期','lmp-ovulationDay','天',0)],'formula':'EDD = LMP + 280 天（40 周）；当前孕周 = 距LMP天数/7','note':'仅供估算，实际分娩可前后浮动两周。','file':'due-date-calc.html'})
add({'ind':'healthcare','cat':'health','title':'按体重给药剂量','icon':'💊','bg':'#fef2f2','desc':'按体重与 mg/kg 计算给药剂量。','inputs':[('weight','体重 kg',20,'any'),('mgkg','剂量 mg/kg',10,'any'),('freq','每日次数',2,'any')],'results':[('日剂量','weight*mgkg','mg/天',1),('单次剂量','weight*mgkg/freq','mg/次',1)],'formula':'日剂量 = 体重 × mg/kg；单次 = 日剂量 / 次数','note':'具体用药务必遵医嘱，本工具仅作计算。','file':'weight-dosage.html'})
add({'ind':'healthcare','cat':'health','title':'儿童退热液量','icon':'🌡️','bg':'#fef2f2','desc':'按体重换算对乙酰氨基酚混悬液体积。','inputs':[('weight','体重 kg',15,'any'),('dose','剂量 mg/kg',15,'any'),('conc','浓度 mg/mL',32,'any')],'results':[('单次药量','weight*dose/conc','mL',1),('日上限次','Math.floor(weight*75/conc/(weight*dose/conc))','次',0)],'formula':'体积 = 体重 × 剂量(mg/kg) / 浓度','note':'对乙酰氨基酚每日上限约 75 mg/kg，请遵说明书。','file':'antipyretic-dose.html'})
add({'ind':'healthcare','cat':'health','title':'心率训练区间','icon':'❤️','bg':'#fef2f2','desc':'按最大心率法估算燃脂与有氧区间。','inputs':[('age','年龄',30,'any'),('rest','静息心率',70,'any'),('intensity','目标强度 %',0.7,'any')],'results':[('最大心率','220-age','bpm',0),('燃脂区间','(220-age-rest)*0.6+rest','bpm',0),('目标心率','(220-age-rest)*intensity+rest','bpm',0)],'formula':'HRmax = 220 − 年龄；区间 = 储备心率 × % + 静息','note':'仅通用公式，个体存在差异。','file':'heart-rate-zones.html'})
add({'ind':'healthcare','cat':'health','title':'eGFR 肾小球滤过率','icon':'🫘','bg':'#fef2f2','desc':'用 CKD-EPI 简化公式估算 eGFR。','inputs':[('scr','血肌酐 mg/dL',1.0,'any'),('age','年龄',50,'any'),('sex','性别 1男/2女',1,'1')],'results':[('eGFR','175*Math.pow(scr,-1.154)*Math.pow(age,-0.203)*(sex===2?0.742:1)','mL/min',1)],'formula':'CKD-EPI 简化：175·Scr⁻¹·¹⁵⁴·年龄⁻⁰·²⁰³·(女×0.742)','note':'eGFR<60 持续三月提示慢性肾病，需就医。','file':'egfr-calculator.html'})
add({'ind':'healthcare','cat':'health','title':'减脂热量缺口','icon':'📉','bg':'#fef2f2','desc':'按目标减重与天数估算每日热量缺口。','inputs':[('loss','目标减重 kg',5,'any'),('days','计划天数',60,'any'),('targetWeight','目标体重 kg',60,'any')],'results':[('总缺口','loss*7700','kcal',0),('日缺口','loss*7700/days','kcal/天',0),('起始体重','targetWeight+loss','kg',1)],'formula':'1 kg 脂肪 ≈ 7700 kcal；日缺口 = 总缺口 / 天数','note':'安全减脂建议日缺口 500–1000 kcal。','file':'fat-loss-deficit.html'})
add({'ind':'healthcare','cat':'health','title':'体表面积 BSA','icon':'📏','bg':'#fef2f2','desc':'用 DuBois 公式估算体表面积。','inputs':[('weight','体重 kg',65,'any'),('height','身高 cm',170,'any'),('age','年龄',30,'any')],'results':[('BSA','0.007184*Math.pow(weight,0.425)*Math.pow(height,0.725)','m²',3)],'formula':'DuBois：BSA = 0.007184·W⁰·⁴²⁵·H⁰·⁷²⁵','note':'用于化疗剂量等医学计算。','file':'bsa-calculator.html'})
add({'ind':'healthcare','cat':'health','title':'呼吸频率评估','icon':'🫁','bg':'#fef2f2','desc':'评估静息呼吸频率是否落在正常范围。','inputs':[('rr','呼吸频率 次/分',16,'any'),('age','年龄',30,'any'),('state','状态 1静息/2运动',1,'1')],'results':[('状态','(()=>{if(rr<12||rr>20)return 3;return 1;})()','等级',0),('偏离正常','Math.abs(rr-16)','次',0),('运动上限参考','(()=>{return state===2?40:20;})()','次/分',0)],'formula':'成人正常静息呼吸 12–20 次/分','note':'异常呼吸请及时就医评估。','file':'resp-rate.html'})
add({'ind':'healthcare','cat':'health','title':'血液酒精浓度 BAC','icon':'🍺','bg':'#fef2f2','desc':'用 Widmark 公式估算血液酒精浓度。','inputs':[('volume','饮酒量 mL',350,'any'),('abv','酒精度 %',0.05,'any'),('weight','体重 kg',70,'any'),('sex','性别 1男/2女',1,'1'),('hours','饮酒后小时',2,'any')],'results':[('BAC','Math.max(0,(volume*abv*0.789)/( (sex===1?0.68:0.55)*weight ) - 0.015*hours)','g/100mL',3)],'formula':'Widmark：BAC = A/(r·W) − β·t；A=体积×酒精度×0.789(g)','note':'r 男0.68/女0.55，β≈0.015/h。请勿酒后驾车，本结果仅供参考。','file':'bac-calculator.html'})
add({'ind':'healthcare','cat':'health','title':'理想体重 Devine','icon':'🧍','bg':'#fef2f2','desc':'用 Devine 公式估算成人理想体重。','inputs':[('height','身高 cm',170,'any'),('sex','性别 1男/2女',1,'1'),('age','年龄',30,'any')],'results':[('理想体重','(()=>{const hIn=height/2.54;return (sex===1?50:45.5)+2.3*(hIn-60);})()','kg',1)],'formula':'Devine：男 50+2.3×(in−60)，女 45.5+2.3×(in−60)','note':'仅作营养评估参考，非健康标准。','file':'ideal-weight.html'})

# ==================== photo (+15) ====================
add({'ind':'photo','cat':'image','title':'曝光值 EV 计算','icon':'📷','bg':'#fefce8','desc':'根据光圈、快门、ISO 计算曝光值。','inputs':[('n','光圈 f',2.8,'any'),('t','快门秒',0.125,'any'),('iso','ISO',100,'any')],'results':[('EV','Math.log2(Math.pow(n,2)/t)','',2),('EV@ISO100','Math.log2(Math.pow(n,2)/t)-Math.log2(iso/100)','',2)],'formula':'EV = log₂(N²/t)；EV₁₀₀ = EV − log₂(ISO/100)','note':'同场景 EV 恒定，调整三者需保持平衡。','file':'exposure-value.html'})
add({'ind':'photo','cat':'image','title':'景深 DOF 计算','icon':'🎯','bg':'#fefce8','desc':'估算对焦距离下的前景深与后景深。','inputs':[('f','焦距 mm',50,'any'),('n','光圈 f',2.8,'any'),('s','对焦距离 m',5,'any'),('c','弥散圆 mm',0.03,'any')],'results':[('超焦距 m','(()=>{const H=f*f/(n*c)+f;return H/1000;})()','m',2),('前景深 m','(()=>{const smm=s*1000,H=f*f/(n*c)+f;return H*smm/(H+smm-f)/1000;})()','m',2),('后景深 m','(()=>{const smm=s*1000,H=f*f/(n*c)+f;return H*smm/(H-smm+f)/1000;})()','m',2)],'formula':'H = f²/(N·c) + f；近/远 = H·S/(H±(S−f))','note':'光圈越小、焦距越短、距离越远，景深越大。','file':'depth-of-field.html'})
add({'ind':'photo','cat':'image','title':'等效焦距换算','icon':'🔭','bg':'#fefce8','desc':'将实际焦距换算为全画幅等效焦距。','inputs':[('focal','实际焦距 mm',35,'any'),('crop','裁剪系数',1.5,'any'),('sensorW','传感器宽 mm',36,'any')],'results':[('全幅等效','focal*crop','mm',1),('等效水平视角','2*Math.atan(sensorW/(2*focal*crop))*180/Math.PI','°',1)],'formula':'等效焦距 = 实际焦距 × 裁剪系数','note':'APS-C 系数约 1.5，M4/3 约 2.0。','file':'equivalent-focal.html'})
add({'ind':'photo','cat':'image','title':'视角 FOV 计算','icon':'👁️','bg':'#fefce8','desc':'根据焦距与传感器尺寸计算水平/垂直视角。','inputs':[('focal','焦距 mm',50,'any'),('sensor','传感器宽 mm',36,'any'),('sensorH','传感器高 mm',24,'any')],'results':[('水平视角','2*Math.atan(sensor/(2*focal))*180/Math.PI','°',1),('垂直视角','2*Math.atan(sensorH/(2*focal))*180/Math.PI','°',1)],'formula':'FOV = 2·atan(d/(2f))','note':'传感器越宽、焦距越短，视角越大。','file':'field-of-view.html'})
add({'ind':'photo','cat':'image','title':'像素与打印尺寸','icon':'🖨️','bg':'#fefce8','desc':'根据像素与 DPI 计算打印尺寸。','inputs':[('wp','宽 像素',6000,'any'),('hp','高 像素',4000,'any'),('dpi','分辨率 DPI',300,'any')],'results':[('打印宽 英寸','wp/dpi','in',2),('打印高 英寸','hp/dpi','in',2),('百万像素','wp*hp/1e6','MP',1)],'formula':'尺寸 = 像素 / DPI','note':'300 DPI 为照片级打印标准。','file':'print-size.html'})
add({'ind':'photo','cat':'image','title':'安全快门速度','icon':'⏱️','bg':'#fefce8','desc':'估算手持拍摄不易模糊的安全快门。','inputs':[('focal','焦距 mm',50,'any'),('crop','裁剪系数',1.5,'any'),('ibis','防抖档数',3,'any')],'results':[('安全快门 秒','1/(focal*crop)','s',4),('建议分母','focal*crop','1/',0),('防抖后安全','1/((focal*crop)*Math.pow(2,ibis))','s',4)],'formula':'安全快门 ≈ 1/(焦距 × 裁剪系数)','note':'低于此速度易因手抖模糊，防抖可放宽。','file':'safe-shutter.html'})
add({'ind':'photo','cat':'image','title':'闪光灯指数 GN','icon':'💡','bg':'#fefce8','desc':'由闪光指数与距离求可用光圈。','inputs':[('gn','闪光指数',40,'any'),('dist','距离 m',5,'any'),('iso','ISO',100,'any')],'results':[('可用光圈(ISO100)','gn/dist','f',1),('最远有效(2.8)','gn/2.8','m',1),('ISO修正系数','Math.sqrt(iso/100)','×',2)],'formula':'光圈 = GN / 距离（ISO100）','note':'ISO 翻倍时有效距离约增 1.4 倍。','file':'flash-gn.html'})
add({'ind':'photo','cat':'image','title':'ND 滤镜快门换算','icon':'🌑','bg':'#fefce8','desc':'计算加 ND 滤镜后的延长快门速度。','inputs':[('base','基准快门 秒',0.01,'any'),('stops','ND 档数',10,'any'),('target','目标快门 秒',10,'any')],'results':[('新快门','base*Math.pow(2,stops)','s',2),('延长倍数','Math.pow(2,stops)','×',0),('达标档数','Math.log2(target/base)','档',1)],'formula':'新快门 = 基准 × 2^档数','note':'ND1000 约 10 档，可将水流拍成丝绢。','file':'nd-filter.html'})
add({'ind':'photo','cat':'image','title':'RAW 文件大小估算','icon':'💾','bg':'#fefce8','desc':'按像素与位深估算 RAW 文件大小。','inputs':[('mp','像素 百万',24,'any'),('bit','位深 bit',14,'any'),('fps','帧率 fps',10,'any')],'results':[('RAW MB','mp*1e6*bit/8/1e6','MB',1),('分钟@10帧 GB','(mp*1e6*bit/8/1e6)*fps*60/1000','GB',2)],'formula':'大小 = 像素 × 位深 / 8','note':'未计压缩与元数据开销。','file':'raw-size.html'})
add({'ind':'photo','cat':'image','title':'超焦距 H 计算','icon':'📐','bg':'#fefce8','desc':'计算对焦到超焦距时的景深范围。','inputs':[('f','焦距 mm',24,'any'),('n','光圈 f',8,'any'),('c','弥散圆 mm',0.03,'any')],'results':[('超焦距 mm','f*f/(n*c)+f','mm',0),('超焦距 m','(f*f/(n*c)+f)/1000','m',2)],'formula':'H = f²/(N·c) + f','note':'对焦到超焦距，景深从 H/2 延伸至无穷远。','file':'hyperfocal.html'})
add({'ind':'photo','cat':'image','title':'存储卡可拍张数','icon':'🗃️','bg':'#fefce8','desc':'根据容量与单张大小估算可拍张数。','inputs':[('card','卡容量 GB',64,'any'),('per','单张 MB',25,'any'),('jpeg','JPEG单张 MB',5,'any')],'results':[('RAW 张数','card*1000/per','张',0),('JPEG 张数','card*1000/jpeg','张',0),('可录分钟@10fps','card*1000/per/10','分',0)],'formula':'张数 = 容量(GB)×1000 / 单张大小(MB)','note':'RAW 通常 20–50 MB，JPEG 较小。','file':'card-capacity.html'})
add({'ind':'photo','cat':'image','title':'日照时长估算','icon':'🌅','bg':'#fefce8','desc':'由纬度与赤纬估算日出日落日照时长。','inputs':[('lat','纬度 °',30,'any'),('decl','赤纬 °',0,'any'),('twilightMin','黄金时刻 分钟',60,'any')],'results':[('日照时长 h','(()=>{const x=-Math.tan(lat*Math.PI/180)*Math.tan(decl*Math.PI/180);return x<=-1?24:x>=1?0:2*Math.acos(x)/15*180/Math.PI;})()','h',2),('黄金时刻 h','twilightMin/60','h',2)],'formula':'日长 = 2·acos(−tanφ·tanδ)/15 小时','note':'赤纬夏至≈23.44，冬至≈−23.44，春分/秋分≈0。黄金时刻为日出后/日落前约 1 小时。','file':'golden-hour.html'})
add({'ind':'photo','cat':'image','title':'动态范围档位','icon':'🌗','bg':'#fefce8','desc':'将亮度比换算为动态范围档位。','inputs':[('maxL','最亮',1024,'any'),('minL','最暗',1,'any'),('sensorStops','传感器档',14,'any')],'results':[('动态范围','Math.log2(maxL/minL)','档',2),('是否溢出现场','Math.log2(maxL/minL)>sensorStops?1:0','0/1',0)],'formula':'DR = log₂(最亮/最暗)','note':'单位为曝光档（stops）。','file':'dynamic-range.html'})
add({'ind':'photo','cat':'image','title':'微距放大率','icon':'🔬','bg':'#fefce8','desc':'根据焦距与物距计算微距放大率。','inputs':[('focal','焦距 mm',100,'any'),('s','物距 mm',150,'any'),('frame','画幅高 mm',24,'any')],'results':[('放大率','focal/(s-focal)','×',2),('像高 mm','focal/(s-focal)*frame','mm',1)],'formula':'放大率 m = f/(S−f)','note':'m=1 为等倍微距，标本与像等大。','file':'macro-magnification.html'})
add({'ind':'photo','cat':'image','title':'包围曝光计划','icon':'🎞️','bg':'#fefce8','desc':'规划包围曝光的张数与 EV 范围。','inputs':[('range','范围档',3,'any'),('step','步进档',1,'any'),('base','基准 EV',0,'any')],'results':[('张数','range/step+1','张',0),('最低EV','base-range/2','EV',1),('最高EV','base+range/2','EV',1)],'formula':'张数 = 范围/步进 + 1；覆盖 [基准−范围/2, 基准+范围/2]','note':'用于 HDR 合成或保险曝光。','file':'bracketing-plan.html'})

# ==================== ai (+27 -> 30) ====================
add({'ind':'ai','cat':'math','title':'模型准确率','icon':'🎯','bg':'#ede9fe','desc':'根据混淆矩阵计算分类准确率。','inputs':[('tp','TP',80,'any'),('tn','TN',60,'any'),('fp','FP',10,'any'),('fn','FN',5,'any')],'results':[('准确率','((tp+tn)/(tp+tn+fp+fn))*100','%',2)],'formula':'Accuracy = (TP+TN)/(TP+TN+FP+FN)','note':'类别不均衡时准确率易误导，应结合其他指标。','file':'model-accuracy.html'})
add({'ind':'ai','cat':'math','title':'精确率与召回率','icon':'🔍','bg':'#ede9fe','desc':'计算二分类的精确率、召回率与 F1。','inputs':[('tp','TP',80,'any'),('fp','FP',20,'any'),('fn','FN',10,'any')],'results':[('精确率','tp/(tp+fp)*100','%',2),('召回率','tp/(tp+fn)*100','%',2),('F1','(()=>{const p=tp/(tp+fp),r=tp/(tp+fn);return 2*p*r/(p+r)*100;})()','%',2)],'formula':'P = TP/(TP+FP)，R = TP/(TP+FN)，F1 = 2PR/(P+R)','note':'精确率关注预测正确性，召回率关注覆盖度。','file':'precision-recall.html'})
add({'ind':'ai','cat':'math','title':'特异度计算','icon':'🧪','bg':'#ede9fe','desc':'评估模型识别负类（特异度）的能力。','inputs':[('tn','TN',60,'any'),('fp','FP',15,'any'),('total','样本总数',200,'any')],'results':[('特异度','tn/(tn+fp)*100','%',2),('假阳性率','fp/(tn+fp)*100','%',2),('负类占比','(tn+fp)/total*100','%',1)],'formula':'特异度 = TN/(TN+FP)','note':'特异度衡量模型识别负类的能力。','file':'specificity.html'})
add({'ind':'ai','cat':'math','title':'交叉熵损失','icon':'📉','bg':'#ede9fe','desc':'计算二分类交叉熵损失。','inputs':[('y','真实标签 0/1',1,'1'),('p','预测概率',0.8,'any'),('n','样本数',1,'any')],'results':[('单样本损失','-(y*Math.log(p)+(1-y)*Math.log(1-p))','',4),('批量损失','-(y*Math.log(p)+(1-y)*Math.log(1-p))*n','',4)],'formula':'L = −(y·log p + (1−y)·log(1−p))','note':'p 应裁剪至 (ε,1−ε) 避免 log(0)。','file':'cross-entropy.html'})
add({'ind':'ai','cat':'math','title':'Transformer 参数量','icon':'🧠','bg':'#ede9fe','desc':'估算 Transformer 主体与嵌入参数量。','inputs':[('L','层数',12,'any'),('d','隐藏维度',768,'any'),('vocab','词表大小',30000,'any')],'results':[('Transformer主体(亿)','12*L*d*d/1e8','亿',2),('嵌入参数(亿)','vocab*d/1e8','亿',2)],'formula':'近似 12·L·d²（含注意力与 FFN）','note':'实际随具体架构大幅浮动。','file':'transformer-params.html'})
add({'ind':'ai','cat':'math','title':'训练算力需求','icon':'⚡','bg':'#ede9fe','desc':'用 Kaplan 缩放律估算训练总算力。','inputs':[('N','参数量(亿)',10,'any'),('D','训练 tokens(亿)',200,'any'),('gpus','GPU 数',8,'any')],'results':[('FLOPs(1e18)','6*N*D','×1e18',2),('单卡月(1e15/s)','6*N*D*1e18/(gpus*1e15*3600*24*30)','月',2)],'formula':'C ≈ 6·N·D（Kaplan 估算）','note':'N、D 单位需一致，结果数量级参考。','file':'training-flops.html'})
add({'ind':'ai','cat':'math','title':'学习率预热步数','icon':'📈','bg':'#ede9fe','desc':'根据总步数与比例计算预热步数。','inputs':[('steps','总步数',10000,'any'),('ratio','预热比例',0.1,'any'),('peakLr','峰值 LR',0.001,'any')],'results':[('预热步数','steps*ratio','步',0),('预热末 LR','peakLr','',6)],'formula':'warmup = 总步数 × 比例','note':'预热可稳定训练初期梯度。','file':'lr-warmup.html'})
add({'ind':'ai','cat':'math','title':'单轮训练时长','icon':'⏱️','bg':'#ede9fe','desc':'估算完成若干轮训练所需时长。','inputs':[('epochs','轮数',5,'any'),('data','数据集规模',50000,'any'),('batch','批次',64,'any'),('speed','吞吐 样本/s',200,'any')],'results':[('总步数','Math.ceil(epochs*data/batch)','步',0),('训练时长','epochs*data/batch/speed/3600','h',2)],'formula':'步数 = ⌈epochs×数据/批次⌉；时长 = 步数/吞吐','note':'未计通信与 I/O 开销。','file':'epoch-time.html'})
add({'ind':'ai','cat':'math','title':'注意力计算量','icon':'🔢','bg':'#ede9fe','desc':'估算单层与全模型注意力 FLOPs。','inputs':[('S','序列长度',1024,'any'),('d','维度',768,'any'),('layers','层数',12,'any')],'results':[('单层 FLOPs','(2*S*S*d + 2*S*S*d)','',0),('全模型 GFLOPs','(2*S*S*d + 2*S*S*d)*layers/1e9','GFLOP',1)],'formula':'单层注意力 ≈ 2·S²·d(QKᵀ) + 2·S²·d(·V)','note':'注意力和序列长度平方相关，长序列代价高。','file':'attention-flops.html'})
add({'ind':'ai','cat':'math','title':'梯度累积步数','icon':'🔁','bg':'#ede9fe','desc':'计算达到目标批次所需的累积步数。','inputs':[('target','目标批次',256,'any'),('perGpu','单卡批次',8,'any'),('gpus','GPU 数',4,'any')],'results':[('累积步数','Math.ceil(target/(perGpu*gpus))','步',0)],'formula':'累积 = ⌈目标批次 /(单卡批次×GPU数)⌉','note':'累积步数越多显存占用越低。','file':'grad-accumulation.html'})
add({'ind':'ai','cat':'math','title':'Token 用量估算','icon':'🔤','bg':'#ede9fe','desc':'按中英文与代码估算 token 用量。','inputs':[('cn','中文字数',500,'any'),('enWords','英文词数',300,'any'),('code','代码片段 tokens',50,'any')],'results':[('估算 tokens','cn/1.5 + enWords/0.75 + code','token',0)],'formula':'中文≈字数/1.5，英文≈词数/0.75','note':'不同分词器差异较大，仅供参考。','file':'token-usage.html'})
add({'ind':'ai','cat':'math','title':'余弦相似度','icon':'📐','bg':'#ede9fe','desc':'计算两个向量的余弦相似度。','inputs':[('a1','向量A1',1,'any'),('a2','A2',2,'any'),('a3','A3',3,'any'),('b1','向量B1',2,'any'),('b2','B2',1,'any'),('b3','B3',0,'any')],'results':[('余弦相似度','(()=>{const a=[a1,a2,a3],b=[b1,b2,b3];let d=0,na=0,nb=0;for(let i=0;i<3;i++){d+=a[i]*b[i];na+=a[i]*a[i];nb+=b[i]*b[i];}return d/(Math.sqrt(na)*Math.sqrt(nb));})()','',4)],'formula':'cos = (A·B)/(|A|·|B|)','note':'取值 −1 到 1，越接近 1 越相似。','file':'cosine-similarity.html'})
add({'ind':'ai','cat':'math','title':'学习率衰减','icon':'📉','bg':'#ede9fe','desc':'按指数衰减计算当前学习率。','inputs':[('lr0','初始 LR',0.001,'any'),('gamma','衰减率',0.95,'any'),('epoch','轮数',10,'any')],'results':[('当前 LR','lr0*Math.pow(gamma,epoch)','',6)],'formula':'LR = LR₀ × γ^epoch','note':'指数衰减常用于后期精调。','file':'lr-decay.html'})
add({'ind':'ai','cat':'math','title':'手肘法 WCSS 降幅','icon':'💡','bg':'#ede9fe','desc':'通过 WCSS 降幅辅助选择聚类 k。','inputs':[('w1','k 时 WCSS',200,'any'),('w2','k+1 时 WCSS',150,'any'),('k','当前 k',3,'any')],'results':[('降幅','(w1-w2)/w1*100','%',1),('比率','w2/w1','',3)],'formula':'降幅 = (WCSS_k − WCSS_{k+1})/WCSS_k','note':'降幅明显减缓处常选为最佳 k。','file':'elbow-wcss.html'})
add({'ind':'ai','cat':'math','title':'AUC 秩次估算','icon':'📊','bg':'#ede9fe','desc':'用 Mann-Whitney U 法由秩和估算 AUC。','inputs':[('nPos','正样本数',20,'any'),('nNeg','负样本数',20,'any'),('sumRank','正样本秩和',500,'any')],'results':[('U 统计','sumRank - nPos*(nPos+1)/2','',0),('AUC','(sumRank - nPos*(nPos+1)/2)/(nPos*nNeg)','',4)],'formula':'U = R₁ − n₁(n₁+1)/2；AUC = U/(n₁n₂)','note':'AUC=0.5 为随机，1 为完美排序。','file':'auc-rank.html'})
add({'ind':'ai','cat':'math','title':'模型显存估算','icon':'🖥️','bg':'#ede9fe','desc':'按参数量与字节数估算权重显存。','inputs':[('params','参数量(十亿)',10,'any'),('bytes','每参数字节',2,'any'),('act','激活 MB',500,'any')],'results':[('权重显存','params*bytes','GB',1),('总显存估算','params*bytes + act/1000','GB',1)],'formula':'显存 ≈ 参数(十亿)×字节 + 激活开销','note':'训练还需优化器状态（通常 2–4 倍权重）。','file':'vram-estimate.html'})
add({'ind':'ai','cat':'math','title':'L1/L2 正则项','icon':'📏','bg':'#ede9fe','desc':'计算权重向量的 L1 与 L2 范数。','inputs':[('w1','权重1',0.5,'any'),('w2','权重2',-0.3,'any'),('w3','权重3',1.2,'any'),('w4','权重4',-0.8,'any')],'results':[('L1 范数','Math.abs(w1)+Math.abs(w2)+Math.abs(w3)+Math.abs(w4)','',3),('L2 范数','Math.sqrt(w1*w1+w2*w2+w3*w3+w4*w4)','',3)],'formula':'L1 = Σ|w|；L2 = √(Σw²)','note':'L1 倾向稀疏，L2 倾向小权重。','file':'l1-l2-regularization.html'})
add({'ind':'ai','cat':'math','title':'数据增强倍数','icon':'🎲','bg':'#ede9fe','desc':'估算数据增强后的样本总量。','inputs':[('orig','原始样本数',1000,'any'),('transforms','变换种类',3,'any'),('factor','每种倍数',2,'any')],'results':[('增强后总量','orig*(1+factor*transforms)','样本',0)],'formula':'总量 = 原始 ×(1 + 倍数 × 变换数)','note':'实际去重后可能低于估算。','file':'augmentation-multiplier.html'})
add({'ind':'ai','cat':'math','title':'最佳轮次选择','icon':'🏆','bg':'#ede9fe','desc':'从若干轮损失中选出最优轮次。','inputs':[('l1','loss 轮1',0.5,'any'),('l2','loss 轮2',0.4,'any'),('l3','loss 轮3',0.45,'any'),('l4','loss 轮4',0.38,'any'),('l5','loss 轮5',0.39,'any')],'results':[('最小 loss','Math.min(l1,l2,l3,l4,l5)','',4),('最佳轮次','(()=>{const a=[l1,l2,l3,l4,l5];let m=0;for(let i=1;i<5;i++)if(a[i]<a[m])m=i;return m+1;})()','轮',0)],'formula':'最佳轮次 = loss 最小者','note':'应结合验证集，避免过拟合轮次。','file':'best-epoch.html'})
add({'ind':'ai','cat':'math','title':'Cohen Kappa 系数','icon':'🤝','bg':'#ede9fe','desc':'计算评价者一致性的 Cohen Kappa。','inputs':[('tp','TP',50,'any'),('tn','TN',40,'any'),('fp','FP',10,'any'),('fn','FN',5,'any')],'results':[('观测一致','(tp+tn)/(tp+tn+fp+fn)','',3),('期望一致','((tp+fp)*(tp+fn)+(tn+fn)*(tn+fp))/Math.pow(tp+tn+fp+fn,2)','',3),('Kappa','(()=>{const tot=tp+tn+fp+fn,Po=(tp+tn)/tot,Pe=((tp+fp)*(tp+fn)+(tn+fn)*(tn+fp))/(tot*tot);return (Po-Pe)/(1-Pe);})()','',3)],'formula':'κ = (Pₒ − Pₑ)/(1 − Pₑ)','note':'κ>0.8 几乎完全一致，<0.2 微弱。','file':'cohens-kappa.html'})
add({'ind':'ai','cat':'math','title':'量化压缩比','icon':'🗜️','bg':'#ede9fe','desc':'估算模型量化（如 FP32→INT8）的压缩比。','inputs':[('params','参数量(百万)',7000,'any'),('fromB','原字节/参',4,'any'),('toB','量化字节/参',1,'any')],'results':[('原大小 MB','params*1e6*fromB/1e6','MB',0),('新大小 MB','params*1e6*toB/1e6','MB',0),('压缩比','fromB/toB','×',1)],'formula':'压缩比 = 原字节/量化字节','note':'FP32→INT8 约 4× 压缩，需校准保精度。','file':'quantization-ratio.html'})
