add({'ind':'ai','cat':'math','title':'推理吞吐估算','icon':'🚀','bg':'#ede9fe','desc':'由生成 token 与时延估算推理吞吐。','inputs':[('tokens','生成 tokens',200,'any'),('sec','耗时 秒',4,'any'),('batch','并发数',1,'any')],'results':[('吞吐 tokens/s','tokens/sec','',1),('人均吞吐','tokens/(sec*batch)','',1)],'formula':'吞吐 = tokens / 耗时；人均 = 吞吐 / 并发','note':'实际受批大小与排队影响。','file':'inference-throughput.html'})
