add({'ind':'ai','cat':'reference','title':'上下文窗口占用','icon':'🪟','bg':'#ede9fe','desc':'计算提示与回复对上下文窗口的占用。','inputs':[('system','系统提示 tokens',500,'any'),('prompt','对话 tokens',1500,'any'),('resp','回复 tokens',1000,'any'),('ctx','上下文上限',128000,'any')],'results':[('已用','system+prompt+resp','token',0),('占用率','(system+prompt+resp)/ctx*100','%',1),('剩余','ctx-(system+prompt+resp)','token',0)],'formula':'占用 = 系统+对话+回复；占用率 = 已用/上限','note':'超出上限需截断或摘要历史。','file':'context-window.html'})
