add({'ind':'eco','cat':'math','title':'绿化覆盖率','icon':'🌳','bg':'#ecfdf5','desc':'计算区域绿化覆盖率。','inputs':[('green','绿地面积 m²',5000,'any'),('total','区域总面积 m²',20000,'any'),('tree','乔木投影面积 m²',800,'any')],'results':[('绿化覆盖率','green/total*100','%',2),('含乔木综合覆盖率','(green+tree*0.5)/total*100','%',2),('未绿化比例', '(total-green)/total*100', '%', 2)],'formula':'绿化覆盖率 = 绿地面积 / 总面积 × 100%','note':'乔木投影按半面积折算为常见做法。','viz':('gauge',0,100)})
add({'ind':'eco','cat':'math','title':'能源效率换算','icon':'⚡','bg':'#ecfdf5','desc':'将不同能源单位换算为标准煤或 kWh。','inputs':[('kwh','电 kWh',100,'any'),('coal_kg','标准煤 kg',0,'any'),('gas_m3','天然气 m³',0,'any')],'results':[('总标准煤','kwh*0.1229+coal_kg+gas_m3*1.2143','kgce',2),('总 kWh','kwh+coal_kg/0.1229+gas_m3*9.88','kWh',2),('总 MJ','(kwh+coal_kg/0.1229+gas_m3*9.88)*3.6','MJ',2)],'formula':'1 kWh ≈ 0.1229 kgce<br>1 m³ 天然气 ≈ 1.2143 kgce ≈ 9.88 kWh','note':'系数为常见近似值。','viz':('bar',0,500)})
add({'ind':'eco','cat':'math','title':'碳汇造林估算','icon':'🌲','bg':'#ecfdf5','desc':'估算森林或造林项目的年碳汇量。','inputs':[('area','面积 公顷',10,'any'),('density','造林密度 株/公顷',1500,'1'),('rate','单株年固碳 kg',5,'any'),('years','年限',10,'1')],'results':[('总株数','area*density','株',0),('年碳汇量','area*density*rate/1000','吨/年',2),('累计碳汇','area*density*rate*years/1000','吨',2)],'formula':'年碳汇 = 面积 × 密度 × 单株固碳量','note':'实际固碳量受树种、气候、林龄影响。','viz':('bar',0,1000)})
add({'ind':'eco','cat':'math','title':'噪声衰减距离','icon':'📉','bg':'#ecfdf5','desc':'估算点声源随距离的声压级衰减。','inputs':[('l0','声源处声压级 dB',100,'any'),('r0','参考距离 m',1,'any'),('r','目标距离 m',50,'any'),('barrier','屏障衰减 dB',0,'any')],'results':[('自由场衰减','20*Math.log10(r/r0)','dB',2),('预测声压级','l0-20*Math.log10(r/r0)-barrier','dB',2),('A 计权修正','l0-20*Math.log10(r/r0)-barrier-1.5','dB(A)',2)],'formula':'点声源衰减 = 20·log₁₀(r/r₀)<br>L_p = L₀ − 20·log₁₀(r/r₀)','note':'未考虑空气吸收和地面效应。','viz':('gauge',0,100)})
add({'ind':'eco','cat':'math','title':'光伏减排估算','icon':'☀️','bg':'#ecfdf5','desc':'估算光伏发电量对应的减排效益。','inputs':[('capacity','装机容量 kW',10,'any'),('hours','年等效满发小时',1200,'any'),('factor','电网排放因子 kgCO₂/kWh',0.5703,'any')],'results':[('年发电量','capacity*hours/1000','万 kWh',2),('年减排量','capacity*hours*factor/1000','吨 CO₂',2),('等效植树','capacity*hours*factor/1000/0.018','棵',0)],'formula':'年发电量 = 装机 × 满发小时<br>减排 = 发电量 × 排放因子','note':'等效植树按每棵年吸收 18kg CO₂ 估算。','viz':('bar',0,50)})
add({'ind':'eco','cat':'math','title':'交通拥堵碳排','icon':'🚗','bg':'#ecfdf5','desc':'估算拥堵导致的额外燃油与碳排放。','inputs':[('vehicles','拥堵车辆数',1000,'1'),('extra_time','平均延误分钟',15,'any'),('fuel_rate','怠速油耗 L/h',0.8,'any'),('days','年拥堵天数',100,'1')],'results':[('单次额外燃油','vehicles*extra_time/60*fuel_rate','L',2),('年额外燃油','vehicles*extra_time/60*fuel_rate*days','L',2),('年额外碳排','vehicles*extra_time/60*fuel_rate*days*2.31/1000','吨',2)],'formula':'额外燃油 = 车辆数 × 延误小时 × 怠速油耗<br>碳排 = 燃油 × 2.31 kg/L','note':'用于评估拥堵治理的环境效益。','viz':('bar',0,100)})
add({'ind':'eco','cat':'math','title':'雨水收集量','icon':'🌧️','bg':'#ecfdf5','desc':'根据屋顶面积和降雨量估算雨水收集潜力。','inputs':[('area','集雨面积 m²',100,'any'),('rain','年降雨量 mm',800,'any'),('eff','收集效率 %',80,'any')],'results':[('年理论收集量','area*rain/1000','m³',2),('年实际收集量','area*rain/1000*eff/100','m³',2),('日平均可用','area*rain/1000*eff/100/365','m³/天',3)],'formula':'收集量 = 面积 × 降雨深度 × 效率','note':'1 mm 降雨 = 1 L/m²。','viz':('bar',0,200)})
add({'ind':'eco','cat':'math','title':'生态足迹估算','icon':'👣','bg':'#ecfdf5','desc':'基于饮食、交通、能源估算个人生态足迹。','inputs':[('meat','肉类消费 kg/周',1,'any'),('drive','驾车 km/周',100,'any'),('elec','家庭用电 kWh/月',200,'any'),('flights','年航班小时',10,'any')],'results':[('饮食 gha','meat*52*0.0034','gha',3),('交通 gha','(drive*52/10000)*0.7+flights*0.5','gha',3),('能源 gha','elec*12*0.0002','gha',3),('总生态足迹','meat*52*0.0034+(drive*52/10000)*0.7+flights*0.5+elec*12*0.0002','gha',3)],'formula':'生态足迹以全球公顷 gha 为单位<br>各活动换算系数为简化近似','note':'仅供参考，详细评估请使用专业方法。','viz':('gauge',0,10)})
add({'ind':'eco','cat':'math','title':'建筑能耗指标','icon':'🏢','bg':'#ecfdf5','desc':'计算单位面积建筑能耗指标。','inputs':[('elec','年用电量 kWh',50000,'any'),('area','建筑面积 m²',2000,'any'),('occupants','使用人数',200,'1')],'results':[('单位面积能耗','elec/area','kWh/m²/年',2),('人均能耗','elec/occupants','kWh/人/年',2),('平方米碳排','elec/area*0.5703','kgCO₂/m²',2)],'formula':'单位面积能耗 = 年用电量 / 建筑面积','note':'用于建筑节能评估对标。','viz':('bar',0,200)})
add({'ind':'eco','cat':'math','title':'污水处理厂能耗','icon':'🏭','bg':'#ecfdf5','desc':'估算污水处理单位能耗。','inputs':[('power','日均电耗 kWh',3000,'any'),('flow','日均处理量 m³',5000,'any'),('lift','提升扬程 m',8,'any')],'results':[('单位能耗','power*24/flow','kWh/m³',3),('吨水电费','power*24/flow*0.6','元/m³',3),('提升能耗占比估算','0.004*lift*100','%',2)],'formula':'电单耗 = 日总电耗 / 日处理量','note':'提升能耗约与扬程成正比。','viz':('bar',0,2)})
add({'ind':'eco','cat':'math','title':'风电减排量','icon':'💨','bg':'#ecfdf5','desc':'估算风力发电量带来的减排量。','inputs':[('capacity','装机容量 MW',50,'any'),('cf','容量因子 %',35,'any'),('factor','电网排放因子',0.5703,'any')],'results':[('年发电量','capacity*cf/100*8760','万 kWh',2),('年减排量','capacity*cf/100*8760*1000*factor/1000','吨 CO₂',2),('等效减少汽车','capacity*cf/100*8760*1000*factor/1000/4.6','辆',0)],'formula':'年发电量 = 装机 × 容量因子 × 8760 小时<br>减排 = 发电量 × 排放因子','note':'等效汽车按年行驶 1.5 万 km、排放 4.6 吨计。','viz':('bar',0,100000)})

