add({'ind':'healthcare','cat':'health','title':'BMI 身体质量指数','icon':'⚖️','bg':'#fef2f2','desc':'根据身高体重计算 BMI 并给出健康分级。','inputs':[('height','身高 cm',170,'any'),('weight','体重 kg',65,'any'),('age','年龄',30,'1')],'results':[('BMI','weight/Math.pow(height/100,2)','',2),('健康分级','(()=>{const b=weight/Math.pow(height/100,2);return b<18.5?1:(b<24?2:(b<28?3:4));})()','级',0),('标准体重范围下限','18.5*Math.pow(height/100,2)','kg',1),('标准体重范围上限','24*Math.pow(height/100,2)','kg',1)],'formula':'BMI = 体重(kg) / 身高(m)²<br>中国成人分级：偏瘦<18.5，正常18.5-23.9，超重24-27.9，肥胖≥28','note':'仅作参考，运动员等肌肉量高者可能不适用。','viz':('gauge',15,35)})
add({'ind':'healthcare','cat':'health','title':'体表面积 BSA','icon':'🧍','bg':'#fef2f2','desc':'用 Du Bois 公式计算成人体表面积。','inputs':[('height','身高 cm',170,'any'),('weight','体重 kg',65,'any'),('formula','公式 1=DuBois 2=Mosteller',1,'1')],'results':[('BSA DuBois','0.007184*Math.pow(weight,0.425)*Math.pow(height,0.725)','m²',3),('BSA Mosteller','Math.sqrt(height*weight/3600)','m²',3),('平均 BSA','(0.007184*Math.pow(weight,0.425)*Math.pow(height,0.725)+Math.sqrt(height*weight/3600))/2','m²',3)],'formula':'Du Bois: BSA = 0.007184 × W^0.425 × H^0.725<br>Mosteller: BSA = √(H×W/3600)','note':'常用于药物剂量计算。','viz':('gauge',1,3)})
add({'ind':'healthcare','cat':'health','title':'eGFR 估算肾小球滤过率','icon':'🩸','bg':'#fef2f2','desc':'用 CKD-EPI 公式估算 eGFR。','inputs':[('scr','血肌酐 µmol/L',80,'any'),('age','年龄',50,'1'),('sex','性别 1=男 0=女',1,'1'),('race','种族系数',1,'any')],'results':[('eGFR','sex?141*Math.pow(Math.min(scr/88.4*0.9,1),-0.411)*Math.pow(Math.max(scr/88.4*0.9,1),-1.209)*Math.pow(0.993,age)*race:141*Math.pow(Math.min(scr/88.4*0.7,1),-0.329)*Math.pow(Math.max(scr/88.4*0.7,1),-1.209)*Math.pow(0.993,age)*1.018*race','mL/min/1.73m²',1),('CKD 分期','(()=>{const g=sex?141*Math.pow(Math.min(scr/88.4*0.9,1),-0.411)*Math.pow(Math.max(scr/88.4*0.9,1),-1.209)*Math.pow(0.993,age)*race:141*Math.pow(Math.min(scr/88.4*0.7,1),-0.329)*Math.pow(Math.max(scr/88.4*0.7,1),-1.209)*Math.pow(0.993,age)*1.018*race;return g>=90?1:(g>=60?2:(g>=30?3:(g>=15?4:5)));})()','期',0)],'formula':'CKD-EPI 公式（简化版）','note':'结果仅供参考，医学诊断需结合临床。','viz':('gauge',0,120)})
add({'ind':'healthcare','cat':'health','title':'CHADS₂-VASc 评分','icon':'❤️','bg':'#fef2f2','desc':'房颤患者卒中风险评估评分。','inputs':[('c','充血性心衰 1=有',0,'1'),('h','高血压 1=有',1,'1'),('a','年龄≥75岁 1=有',0,'1'),('d','糖尿病 1=有',0,'1'),('s','既往卒中/TIA 1=有',0,'1'),('v','血管疾病 1=有',0,'1'),('age65','年龄65-74 1=是',0,'1'),('sex_f','女性 1=是',0,'1')],'results':[('评分','c+h+a+d+s*2+v+age65+sex_f','分',0),('风险分层','(()=>{const s=c+h+a+d+s*2+v+age65+sex_f;return s===0?"低危":(s===1?"低中危":(s===2?"中危":"高危"));})()','',0)],'formula':'C/H/A/D 各 1 分；S（既往卒中/血栓）2 分；V/年龄65-74/女性各 1 分','note':'用于房颤抗凝决策参考。','viz':('gauge',0,9)})
add({'ind':'healthcare','cat':'health','title':'Wells 肺栓塞评分','icon':'🫁','bg':'#fef2f2','desc':'临床评估肺栓塞可能性的评分工具。','inputs':[('dvt','DVT 症状体征',1,'1'),('pe','PE 最可能诊断',1,'1'),('hr','心率 >100',1,'1'),('imm','制动或近期手术',1,'1'),('dvt_hist','既往 DVT/PE',1,'1'),('hem','咯血',0,'1'),('cancer','恶性肿瘤',0,'1')],'results':[('评分','dvt+pe+hr+imm+dvt_hist+hem+cancer','分',0),('临床概率','(()=>{const sc=dvt+pe+hr+imm+dvt_hist+hem+cancer;return sc<=1?"低度":(sc<=6?"中度":"高度");})()','',0)],'formula':'总分 = 各项得分之和 ≤4 低度可能，>4 高度可能','note':'需结合 D-二聚体或影像学检查。','viz':('gauge',0,12)})
add({'ind':'healthcare','cat':'health','title':'儿童剂量换算','icon':'👶','bg':'#fef2f2','desc':'根据成人剂量按体重换算儿童剂量。','inputs':[('adult_dose','成人剂量 mg',500,'any'),('child_weight','儿童体重 kg',20,'any'),('adult_weight','参考成人体重 kg',70,'any'),('max_factor','最大倍数限制',2,'any')],'results':[('按体重剂量','adult_dose*(child_weight/adult_weight)','mg',2),('受限剂量','Math.min(adult_dose*(child_weight/adult_weight), adult_dose*max_factor)','mg',2),('剂量比例','(child_weight/adult_weight)*100','%',2)],'formula':'儿童剂量 = 成人剂量 × (儿童体重 / 成人体重)','note':'实际用药需遵医嘱，不可自行决定。','viz':('bar',0,500)})
add({'ind':'healthcare','cat':'health','title':'理想体重 IBW','icon':'🧮','bg':'#fef2f2','desc':'用 Devine 公式计算成人理想体重。','inputs':[('height','身高 cm',170,'any'),('sex','性别 1=男 0=女',1,'1')],'results':[('IBW','sex?50+0.91*(height-152.4):45.5+0.91*(height-152.4)','kg',1),('上限','(sex?50+0.91*(height-152.4):45.5+0.91*(height-152.4))*1.1','kg',1),('下限','(sex?50+0.91*(height-152.4):45.5+0.91*(height-152.4))*0.9','kg',1)],'formula':'男性 IBW = 50 + 0.91×(身高cm − 152.4)<br>女性 IBW = 45.5 + 0.91×(身高cm − 152.4)','note':'常用于药物剂量调整参考。','viz':('gauge',40,100)})
add({'ind':'healthcare','cat':'health','title':'输液滴速计算','icon':'💉','bg':'#fef2f2','desc':'根据医嘱总量和时间计算输液滴速。','inputs':[('volume','液体总量 mL',500,'any'),('time_min','时间 分钟',120,'any'),('drop','滴系数 滴/mL',20,'1')],'results':[('总滴数','volume*drop','滴',0),('滴速','volume*drop/time_min','滴/分',1),('秒/滴','60/(volume*drop/time_min)','秒/滴',2)],'formula':'滴速(滴/分) = 液体总量 × 滴系数 / 时间(分)','note':'临床需根据患者情况调整。','viz':('gauge',0,200)})
add({'ind':'healthcare','cat':'health','title':'跌倒风险 Morse','icon':'🚶','bg':'#fef2f2','desc':'Morse 跌倒风险评估量表快速计算。','inputs':[('hist','跌倒史',25,'1'),('sec_diag','第二诊断',15,'1'),('aid','助行器 0=无 15=拐杖 30=扶物',15,'1'),('iv','静脉输液',20,'1'),('gait','步态 0=正常 10=虚弱 20=损伤',10,'1'),('mental','精神状态 0=正常 15=高估/遗忘',15,'1')],'results':[('总分','hist+sec_diag+aid+iv+gait+mental','分',0),('风险等级','(()=>{const s=hist+sec_diag+aid+iv+gait+mental;return s<=24?"低风险":(s<=50?"中风险":"高风险");})()','',0)],'formula':'Morse 量表总分 = 各条目得分之和<br>≤24 低风险，25-50 中风险，>50 高风险','note':'用于住院患者跌倒筛查。','viz':('gauge',0,125)})
add({'ind':'healthcare','cat':'health','title':'营养风险 NRS2002','icon':'🥗','bg':'#fef2f2','desc':'NRS-2002 营养风险筛查评分。','inputs':[('bmi','BMI <20.5',1,'1'),('weight_loss','近3月体重下降',1,'1'),('intake','摄食减少',1,'1'),('severity','疾病严重程度 0-3',2,'1'),('age70','年龄≥70',1,'1')],'results':[('营养受损评分','bmi+weight_loss+intake','分',0),('总分','bmi+weight_loss+intake+severity+age70','分',0),('存在营养风险','bmi+weight_loss+intake+severity+age70>=3?"是":"否"','',0)],'formula':'总分 = 营养受损(0-3) + 疾病严重程度(0-3) + 年龄≥70(1)<br>≥3 认为有营养风险','note':'需结合临床营养评估。','viz':('gauge',0,7)})
add({'ind':'healthcare','cat':'health','title':'Parkland 烧伤补液','icon':'🔥','bg':'#fef2f2','desc':'估算成人烧伤后 24 小时 Parkland 补液量。','inputs':[('weight','体重 kg',70,'any'),('tbsa','烧伤面积 %',30,'any'),('hours','已输注时间 h',0,'any')],'results':[('24h 总量','4*weight*tbsa','mL',0),('前8小时','4*weight*tbsa*0.5','mL',0),('后16小时','4*weight*tbsa*0.5','mL',0),('当前应输','4*weight*tbsa*hours/24','mL',0)],'formula':'24h 乳酸林格 = 4 mL × 体重(kg) × 烧伤面积(%)<br>一半在前 8h，一半在后 16h','note':'为估算公式，实际需根据尿量等调整。','viz':('bar',0,10000)})
add({'ind':'healthcare','cat':'health','title':'GFR 肌酐清除率 Cockcroft','icon':'🧪','bg':'#fef2f2','desc':'用 Cockcroft-Gault 公式估算肌酐清除率。','inputs':[('age','年龄',50,'1'),('weight','体重 kg',70,'any'),('scr','血肌酐 µmol/L',80,'any'),('sex','性别 1=男 0=女',1,'1')],'results':[('CrCl','((140-age)*weight)/(scr/88.4)*(sex?1:0.85)','mL/min',2),('调整后体表','((140-age)*weight)/(scr/88.4)*(sex?1:0.85)*1.73/(()=>{return 0.007184*Math.pow(weight,0.425)*Math.pow(170,0.725);})()','mL/min/1.73m²',2)],'formula':'CrCl = (140 − 年龄) × 体重 / (血肌酐 µmol/L ÷ 88.4)<br>女性 ×0.85','note':'用于药物剂量调整。','viz':('gauge',0,150)})
add({'ind':'healthcare','cat':'health','title':'MAP 平均动脉压','icon':'🩺','bg':'#fef2f2','desc':'根据收缩压和舒张压计算平均动脉压。','inputs':[('sbp','收缩压 mmHg',120,'any'),('dbp','舒张压 mmHg',80,'any'),('hr','心率',75,'1')],'results':[('MAP','dbp+(sbp-dbp)/3','mmHg',1),('脉压','sbp-dbp','mmHg',1),('MAP 分级','(()=>{const m=dbp+(sbp-dbp)/3;return m>=70?"正常":(m>=65?"临界":"偏低");})()','',0)],'formula':'MAP ≈ 舒张压 + (收缩压 − 舒张压) / 3','note':'反映器官灌注压力的重要指标。','viz':('gauge',50,130)})
add({'ind':'healthcare','cat':'health','title':'QTc 校正心率','icon':'📈','bg':'#fef2f2','desc':'用 Bazett 公式校正 QT 间期。','inputs':[('qt','QT 间期 ms',400,'any'),('hr','心率 bpm',75,'1'),('formula','公式 1=Bazett 2=Fridericia',1,'1')],'results':[('QTc Bazett','qt/Math.sqrt(60/hr)','ms',1),('QTc Fridericia','qt/Math.cbrt(60/hr)','ms',1),('正常上限','formula===1?440:450','ms',0)],'formula':'Bazett: QTc = QT / √RR<br>Fridericia: QTc = QT / ³√RR<br>RR = 60 / HR','note':'QTc 延长与心律失常风险相关。','viz':('gauge',300,550)})
add({'ind':'healthcare','cat':'health','title':'低钠血症纠正速度','icon':'🧂','bg':'#fef2f2','desc':'估算低钠血症治疗中血钠上升速度。','inputs':[('na_inf','输注液钠浓度 mmol/L',154,'any'),('tbw','总体水 L',42,'any'),('target','目标血钠 mmol/L',130,'any'),('current','当前血钠 mmol/L',118,'any')],'results':[('预期升幅','(na_inf-current)/(tbw+1)','mmol/L',2),('目标差距','target-current','mmol/L',1),('24h 上限提醒','"24h 不超过 8-10 mmol/L"','',0)],'formula':'血钠变化 ≈ (输注液钠 − 当前血钠) / (总体水 + 1)','note':'仅为教学估算，临床必须个体化治疗。','viz':('gauge',0,20)})
add({'ind':'healthcare','cat':'health','title':'纽约心功能分级','icon':'🫀','bg':'#fef2f2','desc':'根据活动受限程度评估心功能分级。','inputs':[('dyspnea','日常活动气短 0-3',1,'1'),('rest','静息症状 0=无 1=有',0,'1'),('limits','活动明显受限 0=无 1=有',0,'1')],'results':[('NYHA 分级','rest?4:(dyspnea===0?1:(limits?3:2))','级',0),('解释','(()=>{const g=rest?4:(dyspnea===0?1:(limits?3:2));return ["I 无症状","II 轻度受限","III 明显受限","IV 静息症状"][g-1];})()','',0)],'formula':'NYHA I-IV 级按症状和活动受限程度划分','note':'用于心衰严重程度评估。','viz':('gauge',1,4)})
add({'ind':'healthcare','cat':'health','title':'阿普加评分 Apgar','icon':'👶','bg':'#fef2f2','desc':'新生儿出生后 1/5 分钟 Apgar 评分。','inputs':[('appearance','皮肤颜色 0-2',2,'1'),('pulse','心率 0-2',2,'1'),('grimace','反射 0-2',2,'1'),('activity','肌张力 0-2',2,'1'),('respiration','呼吸 0-2',2,'1')],'results':[('Apgar 总分','appearance+pulse+grimace+activity+respiration','分',0),('临床意义','(()=>{const s=appearance+pulse+grimace+activity+respiration;return s>=7?"正常":(s>=4?"轻度窒息":"重度窒息");})()','',0)],'formula':'Apgar = 皮肤颜色 + 心率 + 反射 + 肌张力 + 呼吸<br>每项 0-2 分','note':'新生儿窒息快速评估工具。','viz':('gauge',0,10)})
add({'ind':'healthcare','cat':'health','title':' BMI 儿童百分位估算','icon':'📏','bg':'#fef2f2','desc':'根据年龄性别估算儿童 BMI Z 分数（简化）。','inputs':[('age','年龄 岁',10,'any'),('bmi','BMI',18,'any'),('sex','性别 1=男 0=女',1,'1')],'results':[('Z 分数近似','(bmi-(sex?16.5:16.2)-age*0.35)/2.2','',2),('百分位近似','(0.5*(1+Math.erf((bmi-(sex?16.5:16.2)-age*0.35)/(2.2*Math.sqrt(2)))))*100','%',1),('评估','(()=>{const z=(bmi-(sex?16.5:16.2)-age*0.35)/2.2;return z<-2?"偏瘦":(z>2?"超重":"正常");})()','',0)],'formula':'Z ≈ (BMI − 参考均值) / 标准差<br>参考均值随年龄性别变化','note':'本工具为教学简化版，请使用 CDC/WHO 生长曲线。','viz':('gauge',-3,3)})
add({'ind':'healthcare','cat':'health','title':'每日蛋白质需求','icon':'🥩','bg':'#fef2f2','desc':'根据体重和活动水平估算每日蛋白质需求。','inputs':[('weight','体重 kg',70,'any'),('activity','活动系数 1=久坐 1.2=轻 1.5=中 2=高',1.2,'any'),('goal','目标 1=维持 1.2=增肌 0.8=减脂',1.2,'any')],'results':[('维持需求','weight*0.8*activity','g',1),('目标需求','weight*0.8*activity*goal','g',1),('每餐建议','weight*0.8*activity*goal/4','g',1)],'formula':'蛋白质需求 = 体重 × 0.8 g/kg × 活动系数 × 目标系数','note':'运动员或特殊疾病需调整。','viz':('bar',0,200)})

