add({'ind':'photo','cat':'image','title':'景深计算器','icon':'📷','bg':'#fff7ed','desc':'计算摄影景深、近界与远界。','inputs':[('focal','焦距 mm',50,'any'),('aperture','光圈 f 值',2.8,'any'),('coc','弥散圆 mm',0.03,'any'),('distance','对焦距离 m',3,'any')],'results':[('超焦距','focal*focal/(aperture*coc)/1000','m',2),('近景深','(distance*1000*(distance*1000-focal))/(distance*1000+focal*focal/(aperture*coc))/1000','m',2),('远景深','(distance*1000*(distance*1000-focal))/(distance*1000-focal*focal/(aperture*coc))/1000','m',2),('总景深','((distance*1000*(distance*1000-focal))/(distance*1000-focal*focal/(aperture*coc))-(distance*1000*(distance*1000-focal))/(distance*1000+focal*focal/(aperture*coc)))/1000','m',2)],'formula':'超焦距 H = f² / (N · c)<br>景深 = H·d² / (H² − d²)（简化近似）','note':'对焦距离需大于焦距。','viz':('bar',0,20)})
add({'ind':'photo','cat':'image','title':'曝光值 EV','icon':'☀️','bg':'#fff7ed','desc':'根据光圈、快门、ISO 计算曝光值。','inputs':[('aperture','光圈 f 值',2.8,'any'),('shutter','快门时间 s',0.01,'any'),('iso','ISO',100,'any')],'results':[('EV100','Math.log2(Math.pow(aperture,2)/shutter)-Math.log2(iso/100)','',2),('实际 EV','Math.log2(Math.pow(aperture,2)/shutter)','',2),('亮度参考','(()=>{const ev=Math.log2(Math.pow(aperture,2)/shutter)-Math.log2(iso/100);return ev>=15?"晴天":(ev>=12?"多云":(ev>=9?"阴天":(ev>=6?"室内明亮":"室内暗光")));})()','',0)],'formula':'EV = log₂(N² / t) − log₂(ISO/100)<br>N 为光圈值，t 为快门时间','note':'EV 越低画面越亮。','viz':('gauge',0,20)})
add({'ind':'photo','cat':'image','title':'等效焦距','icon':'🔍','bg':'#fff7ed','desc':'计算不同画幅下的等效焦距。','inputs':[('focal','镜头焦距 mm',50,'any'),('crop','裁切系数 1=全幅 1.5=APS-C 2=M43',1.5,'any'),('target','目标画幅系数',1,'any')],'results':[('当前等效焦距','focal*crop','mm',0),('目标等效焦距','focal*target','mm',0),('视角变化比', 'crop/target', '', 2)],'formula':'等效焦距 = 实际焦距 × 裁切系数','note':'全画幅基准系数为 1。','viz':('bar',0,200)})
add({'ind':'photo','cat':'image','title':'闪光指数计算','icon':'⚡','bg':'#fff7ed','desc':'根据闪光指数和光圈计算闪光距离。','inputs':[('gn','闪光指数 m',36,'any'),('aperture','光圈 f 值',4,'any'),('iso','ISO',100,'any')],'results':[('ISO100 距离', 'gn/aperture', 'm', 2),('实际 ISO 距离', 'gn/aperture*Math.sqrt(iso/100)', 'm', 2),('所需光圈', 'gn/10', 'f', 1)],'formula':'距离 = GN / f<br>ISO 加倍，距离 ×√2','note':'GN 通常以 ISO100 标定。','viz':('bar',0,30)})
add({'ind':'photo','cat':'image','title':'打印分辨率 DPI','icon':'🖨️','bg':'#fff7ed','desc':'计算照片打印所需像素与 DPI。','inputs':[('width_px','宽度像素',3000,'1'),('height_px','高度像素',2000,'1'),('print_w','打印宽度 cm',30,'any'),('dpi','目标 DPI',300,'any')],'results':[('打印高度','height_px/width_px*print_w','cm',1),('所需像素','print_w/2.54*dpi','px',0),('当前 DPI','width_px/(print_w/2.54)','dpi',1),('是否足够','width_px/(print_w/2.54)>=dpi?"是":"否"','',0)],'formula':'DPI = 像素数 / 英寸长度<br>英寸 = 厘米 / 2.54','note':'300 DPI 常用于高质量打印。','viz':('gauge',0,600)})
add({'ind':'photo','cat':'image','title':'星轨拍摄时长','icon':'🌌','bg':'#fff7ed','desc':'估算不出现明显拖线的最长曝光时间。','inputs':[('focal','焦距 mm',24,'any'),('crop','裁切系数',1,'any'),('pixels','传感器长边像素',6000,'1'),('tolerance','可接受移动像素',5,'1')],'results':[('500 法则','500/(focal*crop)','秒',1),('NPF 近似','(35*focal+30*pixels/1000)/(focal*crop)/tolerance','秒',2),('建议最长时间','Math.min(500/(focal*crop),(35*focal+30*pixels/1000)/(focal*crop)/tolerance)','秒',1)],'formula':'500 法则：曝光秒数 ≤ 500 / (焦距 × 裁切系数)<br>NPF 更精确，考虑像素尺寸','note':'用于星空摄影避免星点拖线。','viz':('gauge',0,60)})
add({'ind':'photo','cat':'image','title':'对焦超焦距','icon':'🎯','bg':'#fff7ed','desc':'计算并应用超焦距对焦时的清晰范围。','inputs':[('focal','焦距 mm',35,'any'),('aperture','光圈 f 值',8,'any'),('coc','弥散圆 mm',0.03,'any')],'results':[('超焦距 H','focal*focal/(aperture*coc)/1000','m',2),('对焦 H 时近界', '(focal*focal/(aperture*coc)/1000)/2', 'm', 2),('对焦 H 时远界','∞','',0),('光圈 f/16 超焦距', 'focal*focal/(16*coc)/1000', 'm', 2)],'formula':'H = f² / (N · c)<br>对焦 H 时，景深从 H/2 到无穷远','note':'风景摄影常用技巧。','viz':('bar',0,50)})
add({'ind':'photo','cat':'image','title':'视角计算器','icon':'👁️','bg':'#fff7ed','desc':'计算镜头水平与垂直视角。','inputs':[('focal','焦距 mm',50,'any'),('sensor_w','传感器宽度 mm',36,'any'),('sensor_h','传感器高度 mm',24,'any')],'results':[('水平视角', '2*Math.atan(sensor_w/(2*focal))*180/Math.PI', '°', 2),('垂直视角', '2*Math.atan(sensor_h/(2*focal))*180/Math.PI', '°', 2),('对角线视角', '2*Math.atan(Math.sqrt(sensor_w*sensor_w+sensor_h*sensor_h)/(2*focal))*180/Math.PI', '°', 2)],'formula':'视角 = 2 · arctan(传感器边长 / (2 · 焦距))','note':'全画幅默认 36×24 mm。','viz':('gauge',0,120)})
add({'ind':'photo','cat':'image','title':'放大倍率','icon':'🔬','bg':'#fff7ed','desc':'计算微距摄影的放大倍率。','inputs':[('sensor_w','传感器宽度 mm',36,'any'),('object_w','被摄物实际宽度 mm',10,'any'),('image_w','成像宽度 mm',36,'any')],'results':[('放大倍率', 'image_w/object_w', 'x', 2),('传感器占比', 'image_w/sensor_w*100', '%', 2),('可拍最大物体', 'sensor_w', 'mm', 0)],'formula':'放大倍率 = 成像大小 / 实际大小','note':'1:1 表示成像与实物等大。','viz':('gauge',0,5)})
add({'ind':'photo','cat':'image','title':'色温换算 mired','icon':'🌡️','bg':'#fff7ed','desc':'在色温与 mired 微倒数之间换算。','inputs':[('k','色温 K',5600,'1'),('shift','偏移 mired',0,'any')],'results':[('Mired 值', '1000000/k', 'mired', 1),('偏移后色温', '1000000/(1000000/k+shift)', 'K', 0),('偏移量', 'shift', 'mired', 1)],'formula':'Mired = 1,000,000 / K<br>K = 1,000,000 / mired','note':'摄影滤光片常用 mired 描述色温偏移。','viz':('gauge',0,500)})
add({'ind':'photo','cat':'image','title':'文件大小估算','icon':'💾','bg':'#fff7ed','desc':'估算 RAW/JPEG 图像文件大小。','inputs':[('mp','像素百万',24,'any'),('depth','位深',14,'1'),('compression','压缩比 1=无损 3=RAW 10=JPEG',3,'any')],'results':[('未压缩 MB','mp*1000000*depth/8/1024/1024','MB',2),('压缩后估算','mp*1000000*depth/8/1024/1024/compression','MB',2),('每像素 bit', 'depth', 'bit', 0)],'formula':'未压缩大小 = 像素数 × 位深 / 8<br>压缩后 ≈ 未压缩 / 压缩比','note':'实际大小因图像内容而异。','viz':('bar',0,100)})
add({'ind':'photo','cat':'image','title':'衍射极限光圈','icon':'🔮','bg':'#fff7ed','desc':'估算传感器像素密度下的衍射极限光圈。','inputs':[('pitch','像素间距 µm',5,'any'),('wavelength','光波长 nm',550,'any'),('coarse','容许模糊圈倍数',2,'any')],'results':[('艾里斑直径 µm','2.44*wavelength/1000','µm',2),('建议最小光圈','coarse*pitch/(2.44*wavelength/1000)','f',1),('像素级极限', 'pitch/(2.44*wavelength/1000)', 'f', 1)],'formula':'衍射模糊 ≈ 2.44 · λ · N<br>当模糊大于像素间距时光圈过小的影响可见','note':'小像素传感器更早遇到衍射极限。','viz':('gauge',0,32)})
add({'ind':'photo','cat':'image','title':'包围曝光张数','icon':'📸','bg':'#fff7ed','desc':'计算 HDR 包围曝光所需张数与步长。','inputs':[('ev_total','总 EV 范围',12,'any'),('step','步长 EV',2,'any'),('base','基准 EV',0,'any')],'results':[('所需张数','Math.ceil(ev_total/step)*2+1','张',0),('实际覆盖 EV','Math.ceil(ev_total/step)*step*2','EV',0),('档位列表', 'base+" ±"+Math.ceil(ev_total/step)*step+" EV"', '', 0)],'formula':'张数 = 2 × ceil(总范围 / 步长) + 1','note':'确保相邻两张重叠至少 1 EV。','viz':('bar',0,15)})
add({'ind':'photo','cat':'image','title':'摇摄快门速度','icon':'🏎️','bg':'#fff7ed','desc':'估算追随拍摄时的推荐快门速度。','inputs':[('speed','物体速度 km/h',50,'any'),('distance','距离 m',10,'any'),('focal','焦距 mm',100,'any')],'results':[('物体横向速度', 'speed*1000/3600', 'm/s', 2),('视角移动速度', 'speed*1000/3600/distance*180/Math.PI', '°/s', 2),('推荐快门', 'Math.max(1/4000,1/(focal*speed*1000/3600/distance*180/Math.PI/10))', 's', 4),('推荐分母','Math.round(1/Math.max(1/4000,1/(focal*speed*1000/3600/distance*180/Math.PI/10)))','',0)],'formula':'推荐快门 ≈ 1 / (焦距 × 角速度 / 10)<br>角速度 ≈ 横向速度 / 距离','note':'根据目标模糊效果可上下调整。','viz':('bar',0,1000)})

