add({'ind':'ai','cat':'dev','title':'分类准确率评估','icon':'🤖','bg':'#ede9fe','desc':'根据 TP/FP/FN/TN 计算准确率、精确率、召回率、F1。','inputs':[('tp','真正例 TP',80,'1'),('fp','假正例 FP',10,'1'),('fn','假反例 FN',15,'1'),('tn','真反例 TN',95,'1')],'results':[('准确率','(tp+tn)/(tp+fp+fn+tn)*100','%',2),('精确率','tp/(tp+fp)*100','%',2),('召回率','tp/(tp+fn)*100','%',2),('F1 分数','2*tp/(2*tp+fp+fn)*100','%',2)],'formula':'Accuracy = (TP+TN)/All<br>Precision = TP/(TP+FP)<br>Recall = TP/(TP+FN)<br>F1 = 2·P·R/(P+R)','note':'用于二分类模型评估。','viz':('bar',0,100)})
add({'ind':'ai','cat':'dev','title':'均方误差 RMSE','icon':'📉','bg':'#ede9fe','desc':'计算回归预测的 MSE、RMSE、MAE、R²。','inputs':[('n','样本数',5,'1'),('sum_y','真实值之和',25,'any'),('sum_p','预测值之和',26,'any'),('sum_y2','真实值平方和',135,'any'),('sum_p2','预测值平方和',142,'any'),('sum_yp','真实×预测之和',130,'any')],'results':[('MSE','(sum_y2-2*sum_yp+sum_p2)/n','',4),('RMSE','Math.sqrt((sum_y2-2*sum_yp+sum_p2)/n)','',4),('MAE','Math.abs(sum_y-sum_p)/n','',4),('R²','(()=>{const ssRes=sum_y2-2*sum_yp+sum_p2;const meanY=sum_y/n;const ssTot=sum_y2-n*meanY*meanY;return ssTot?1-ssRes/ssTot:0;})()','',4)],'formula':'MSE = Σ(y−p)² / n<br>RMSE = √MSE<br>R² = 1 − SS_res/SS_tot','note':'输入聚合统计量即可计算。','viz':('bar',0,100)})
add({'ind':'ai','cat':'dev','title':'Sigmoid 输出','icon':'S','bg':'#ede9fe','desc':'计算 Sigmoid 函数值与分类阈值。','inputs':[('z','输入 z',2.0,'any'),('threshold','分类阈值',0.5,'any')],'results':[('Sigmoid', '1/(1+Math.exp(-z))', '', 6),('分类结果', '1/(1+Math.exp(-z))>=threshold?"正类":"负类"', '', 0),('对数几率', 'Math.log(1/(1+Math.exp(-z))/(1-1/(1+Math.exp(-z))))', '', 4)],'formula':'σ(z) = 1 / (1 + e⁻ᶻ)','note':'将任意实数映射到 (0,1)。','viz':('gauge',0,1)})
add({'ind':'ai','cat':'dev','title':'ReLU 与 LeakyReLU','icon':'R','bg':'#ede9fe','desc':'可视化 ReLU 激活函数输出。','inputs':[('x','输入 x',-2,'any'),('alpha','LeakyReLU 斜率 α',0.1,'any')],'results':[('ReLU', 'Math.max(0,x)', '', 2),('LeakyReLU', 'x>=0?x:alpha*x', '', 2),('ELU', 'x>=0?x:alpha*(Math.exp(x)-1)', '', 2)],'formula':'ReLU(x) = max(0, x)<br>LeakyReLU(x) = max(αx, x)<br>ELU(x) = x if x≥0 else α(eˣ−1)','note':'激活函数是神经网络非线性的来源。','viz':('gauge',-5,5)})
add({'ind':'ai','cat':'dev','title':'Softmax 概率','icon':'🎲','bg':'#ede9fe','desc':'将一组 logits 转换为概率分布。','inputs':[('z1','Logit 1',2.0,'any'),('z2','Logit 2',1.0,'any'),('z3','Logit 3',0.5,'any'),('z4','Logit 4',0.2,'any')],'results':[('P1','Math.exp(z1)/(Math.exp(z1)+Math.exp(z2)+Math.exp(z3)+Math.exp(z4))*100','%',2),('P2','Math.exp(z2)/(Math.exp(z1)+Math.exp(z2)+Math.exp(z3)+Math.exp(z4))*100','%',2),('P3','Math.exp(z3)/(Math.exp(z1)+Math.exp(z2)+Math.exp(z3)+Math.exp(z4))*100','%',2),('P4','Math.exp(z4)/(Math.exp(z1)+Math.exp(z2)+Math.exp(z3)+Math.exp(z4))*100','%',2)],'formula':'Pᵢ = e^zᵢ / Σe^zⱼ','note':'Softmax 输出概率之和为 1。','viz':('bar',0,100)})
add({'ind':'ai','cat':'dev','title':'交叉熵损失','icon':'🔥','bg':'#ede9fe','desc':'计算二分类或Softmax交叉熵损失。','inputs':[('y','真实标签 0-1',1,'any'),('p','预测概率',0.8,'any'),('eps','平滑项',1e-7,'any')],'results':[('二分类交叉熵','-(y*Math.log(p+eps)+(1-y)*Math.log(1-p+eps))','',4),('KL 散度', 'y*Math.log((y+eps)/(p+eps))', '', 4),('错误预测损失','-(1*Math.log(eps)+(0)*Math.log(1-eps))','',2)],'formula':'L = −[y·log(p) + (1−y)·log(1−p)]','note':'预测越偏离标签，损失越大。','viz':('bar',0,10)})
add({'ind':'ai','cat':'dev','title':'学习率衰减','icon':'📉','bg':'#ede9fe','desc':'计算 Step/Exponential/Cosine 学习率衰减。','inputs':[('lr0','初始学习率',0.1,'any'),('epoch','当前 epoch',10,'1'),('decay','衰减率',0.1,'any'),('mode','模式 1=step 2=exp 3=cos',2,'1')],'results':[('Step 衰减', 'lr0/(1+decay*epoch)', '', 6),('Exponential', 'lr0*Math.exp(-decay*epoch)', '', 6),('Cosine', 'lr0*(0.5+0.5*Math.cos(epoch*decay*Math.PI))', '', 6)],'formula':'Step: lr = lr₀/(1+decay·epoch)<br>Exp: lr = lr₀·e^(−decay·epoch)<br>Cos: lr = lr₀·0.5(1+cos(π·epoch/T))','note':'实际 T 为总 epoch。','viz':('bar',0,0.2)})
add({'ind':'ai','cat':'dev','title':'特征缩放 Min-Max','icon':'📏','bg':'#ede9fe','desc':'将特征值缩放到 [0,1] 或 [−1,1]。','inputs':[('x','原始值',75,'any'),('min','最小值',50,'any'),('max','最大值',100,'any'),('range','目标范围 1=[0,1] 2=[-1,1]',1,'1')],'results':[('Min-Max [0,1]','(x-min)/(max-min)','',4),('Min-Max [-1,1]','2*(x-min)/(max-min)-1','',4),('Z-score','(x-(min+max)/2)/((max-min)/2)','',4)],'formula':'x\' = (x − min) / (max − min)<br>映射到 [−1,1]：2x\' − 1','note':'注意 max 不能等于 min。','viz':('gauge',-1,1)})
add({'ind':'ai','cat':'dev','title':'欧氏距离','icon':'📐','bg':'#ede9fe','desc':'计算两个向量之间的欧氏距离与余弦相似度。','inputs':[('a1','A1',1,'any'),('a2','A2',2,'any'),('a3','A3',3,'any'),('b1','B1',4,'any'),('b2','B2',5,'any'),('b3','B3',6,'any')],'results':[('欧氏距离', 'Math.sqrt(Math.pow(a1-b1,2)+Math.pow(a2-b2,2)+Math.pow(a3-b3,2))', '', 4),('曼哈顿距离', 'Math.abs(a1-b1)+Math.abs(a2-b2)+Math.abs(a3-b3)', '', 4),('余弦相似度','((a1*b1+a2*b2+a3*b3)/(Math.sqrt(a1*a1+a2*a2+a3*a3)*Math.sqrt(b1*b1+b2*b2+b3*b3)))||0','',4)],'formula':'欧氏距离 = √Σ(aᵢ−bᵢ)²<br>余弦相似度 = A·B / (|A||B|)','note':'余弦相似度范围为 [−1, 1]。','viz':('bar',0,10)})
add({'ind':'ai','cat':'dev','title':'批量大小迭代次数','icon':'🔄','bg':'#ede9fe','desc':'根据数据集大小和 batch size 计算训练迭代次数。','inputs':[('samples','样本总数',10000,'1'),('batch','Batch size',32,'1'),('epochs','训练 epoch 数',10,'1')],'results':[('每轮步数', 'Math.ceil(samples/batch)', '步', 0),('总步数', 'Math.ceil(samples/batch)*epochs', '步', 0),('最后一批大小', 'samples%batch||batch', '个', 0)],'formula':'steps_per_epoch = ceil(样本数 / batch_size)<br>总步数 = steps × epochs','note':'最后一批可能不满。','viz':('bar',0,5000)})
add({'ind':'ai','cat':'dev','title':'参数数量估算','icon':'🧮','bg':'#ede9fe','desc':'估算全连接层和卷积层的参数数量。','inputs':[('in_','输入维度',784,'1'),('out_','输出维度',128,'1'),('bias','是否含偏置 1=是',1,'1'),('conv','是否卷积 1=是',0,'1')],'results':[('全连接参数', 'in_*out_+out_*bias', '个', 0),('卷积核参数', 'conv?(in_*out_*9+out_*bias):0', '个', 0),('显存估算 MB','(in_*out_+out_*bias)*4/1024/1024','MB',4)],'formula':'全连接：params = in × out + out（bias）<br>卷积 3×3：params = in × out × 9 + out','note':'用于快速估算模型规模。','viz':('bar',0,1000000)})
add({'ind':'ai','cat':'dev','title':'Token 数量估算','icon':'📝','bg':'#ede9fe','desc':'根据文本长度估算大模型 Token 数量。','inputs':[('chars','字符数',500,'1'),('lang','语言系数 1=中文 0.3=英文',1,'any'),('overlap','平均词长',1.5,'any')],'results':[('估算 Token 数', 'Math.ceil(chars*lang/overlap)', '个', 0),('英文参考', 'Math.ceil(chars*0.3/1.5)', '个', 0),('成本参考（每 1M tokens $2）', 'Math.ceil(chars*lang/overlap)/1000000*2', 'USD', 4)],'formula':'中文 ≈ 0.6-1 token/字<br>英文 ≈ 0.2-0.25 token/字','note':'不同分词器结果差异较大。','viz':('bar',0,1000)})
add({'ind':'ai','cat':'dev','title':'混淆矩阵指标','icon':'🧩','bg':'#ede9fe','desc':'输入 TP/FP/FN/TN 计算马修斯相关系数 MCC 和 FPR。','inputs':[('tp','TP',80,'1'),('fp','FP',10,'1'),('fn','FN',15,'1'),('tn','TN',95,'1')],'results':[('MCC','((tp*tn-fp*fn)/Math.sqrt((tp+fp)*(tp+fn)*(tn+fp)*(tn+fn)))||0','',4),('假正率 FPR', 'fp/(fp+tn)*100', '%', 2),('特异度 TNR', 'tn/(fp+tn)*100', '%', 2),('FDR', 'fp/(tp+fp)*100', '%', 2)],'formula':'MCC = (TP·TN − FP·FN) / √[(TP+FP)(TP+FN)(TN+FP)(TN+FN)]<br>FPR = FP/(FP+TN)','note':'MCC 范围 [−1,1]，是均衡的评估指标。','viz':('gauge',-1,1)})
add({'ind':'ai','cat':'dev','title':'ROC AUC 近似','icon':'📈','bg':'#ede9fe','desc':'用正例与负例得分估算 AUC。','inputs':[('pos_mean','正例平均得分',0.8,'any'),('neg_mean','负例平均得分',0.3,'any'),('pos_std','正例标准差',0.1,'any'),('neg_std','负例标准差',0.1,'any')],'results':[('AUC 近似', '0.5+0.5*Math.erf((pos_mean-neg_mean)/Math.sqrt(2*(pos_std*pos_std+neg_std*neg_std)))', '', 4),('分离度', '(pos_mean-neg_mean)/Math.sqrt((pos_std*pos_std+neg_std*neg_std)/2)', '', 4),('可区分性', '(pos_mean-neg_mean)/(pos_std+neg_std)', '', 4)],'formula':'AUC ≈ Φ((μ₊ − μ₋) / √(σ₊² + σ₋²))','note':'基于正态分布假设的近似。','viz':('gauge',0,1)})
add({'ind':'ai','cat':'dev','title':'梯度下降一步','icon':'⬇️','bg':'#ede9fe','desc':'模拟单变量梯度下降的一次参数更新。','inputs':[('w','当前权重',5,'any'),('grad','梯度',2,'any'),('lr','学习率',0.1,'any'),('lambda','L2 正则化',0.01,'any')],'results':[('新权重','w-lr*(grad+2*lambda*w)','',4),('权重变化','-lr*(grad+2*lambda*w)','',4),('L2 惩罚项','2*lambda*w','',4)],'formula':'w = w − lr·(∇L + 2λw)','note':'L2 正则化使权重向零收缩。','viz':('gauge',-10,10)})
add({'ind':'ai','cat':'dev','title':'信息增益近似','icon':'💡','bg':'#ede9fe','desc':'用基尼指数或熵评估二分类分裂前后的不纯度变化。','inputs':[('p_root','根节点正例比例',0.5,'any'),('p_left','左子树正例比例',0.3,'any'),('w_left','左子树权重',0.4,'any'),('p_right','右子树正例比例',0.7,'any')],'results':[('根基尼', '2*p_root*(1-p_root)', '', 4),('加权子基尼', 'w_left*2*p_left*(1-p_left)+(1-w_left)*2*p_right*(1-p_right)', '', 4),('基尼增益', '2*p_root*(1-p_root)-(w_left*2*p_left*(1-p_left)+(1-w_left)*2*p_right*(1-p_right))', '', 4),('根熵','-(p_root*Math.log2(p_root+1e-10)+(1-p_root)*Math.log2(1-p_root+1e-10))','',4)],'formula':'基尼 = 2p(1−p)<br>熵 = −p·log₂p − (1−p)·log₂(1−p)<br>增益 = 父不纯度 − 加权子不纯度','note':'决策树分裂选择增益最大的特征。','viz':('bar',0,1)})
add({'ind':'ai','cat':'dev','title':'聚类 K-Means 代价','icon':'🎯','bg':'#ede9fe','desc':'估算 K-Means 聚类的惯性 inertia。','inputs':[('n','样本数',1000,'1'),('k','聚类数',5,'1'),('dim','维度',10,'1'),('spread','簇内散布',2,'any')],'results':[('Inertia 估算', 'n*dim*spread*spread/k', '', 2),('每个簇样本', 'Math.ceil(n/k)', '个', 0),(' Davies-Bouldin 估算', 'k*spread/(spread+0.1)', '', 2)],'formula':'Inertia ≈ ΣΣ||x − μ||²','note':'Inertia 越小簇内越紧密。','viz':('bar',0,10000)})
add({'ind':'ai','cat':'dev','title':'图像卷积输出尺寸','icon':'🖼️','bg':'#ede9fe','desc':'计算卷积/池化后的特征图尺寸。','inputs':[('w','输入尺寸',224,'1'),('k','卷积核大小',3,'1'),('s','步长',1,'1'),('p','填充',1,'1'),('d','空洞率',1,'1')],'results':[('输出尺寸', 'Math.floor((w+2*p-k-(k-1)*(d-1))/s)+1', '', 0),('感受野', 'k+(k-1)*(d-1)', '', 0),('参数减少比', '1-Math.pow((k+(k-1)*(d-1))/w,2)', '', 4)],'formula':'Out = ⌊(W + 2P − K − (K−1)(D−1)) / S⌋ + 1','note':'用于设计 CNN 网络结构。','viz':('bar',0,224)})
add({'ind':'ai','cat':'dev','title':'过拟合诊断','icon':'🔍','bg':'#ede9fe','desc':'根据训练/验证损失判断过拟合程度。','inputs':[('train_loss','训练损失',0.2,'any'),('val_loss','验证损失',0.6,'any'),('train_acc','训练准确率 %',95,'any'),('val_acc','验证准确率 %',80,'any')],'results':[('损失差距','val_loss-train_loss','',4),('准确率差距','train_acc-val_acc','%',2),('过拟合风险','val_loss-train_loss>0.3||train_acc-val_acc>10?"高":(val_loss-train_loss>0.1?"中":"低")','',0),('建议','val_loss-train_loss>0.3?"增加正则化/数据扩增":"继续训练或早停"','',0)],'formula':'过拟合：训练表现远好于验证表现','note':'准确率差距 >10% 或损失差距 >0.3 通常视为过拟合信号。','viz':('bar',0,50)})
add({'ind':'ai','cat':'dev','title':'Dropout 保留期望','icon':'🎲','bg':'#ede9fe','desc':'计算 Dropout 后的期望输出与缩放因子。','inputs':[('rate','Dropout 率',0.5,'any'),('x','输入值',2,'any'),('n','神经元数',100,'1')],'results':[('保留概率', '1-rate', '', 2),('期望输出', 'x*(1-rate)', '', 2),('期望活跃神经元', 'n*(1-rate)', '个', 0),('缩放因子', '1/(1-rate)', '', 2)],'formula':'期望输出 = x · (1 − p)<br>推理时缩放 1/(1−p)','note':'Dropout 率通常取 0.2-0.5。','viz':('bar',0,5)})
add({'ind':'ai','cat':'dev','title':'数据增强有效量','icon':'🔄','bg':'#ede9fe','desc':'估算数据增强后的等效训练样本量。','inputs':[('base','原始样本数',1000,'1'),('aug','每种样本增强次数',5,'1'),('diversity','增强多样性系数 0-1',0.5,'any')],'results':[('理论扩充量','base*aug','张',0),('有效等效量','base*(1+(aug-1)*diversity)','张',0),('避免过拟合建议','base*(1+(aug-1)*diversity)>5000?"数据量充足":"建议继续收集真实数据"','',0)],'formula':'有效量 ≈ 原始样本 × [1 + (aug − 1) × 多样性系数]','note':'过度增强可能引入噪声。','viz':('bar',0,10000)})
add({'ind':'ai','cat':'dev','title':'早停耐心估算','icon':'⏱️','bg':'#ede9fe','desc':'根据训练速度估算早停 patience 与总时间。','inputs':[('epoch_time','每 epoch 秒',60,'any'),('patience','耐心 epoch 数',10,'1'),('min_epochs','最小 epoch',50,'1')],'results':[('早停等待时间', 'patience*epoch_time/60', '分钟', 1),('最小训练时间', 'min_epochs*epoch_time/60', '分钟', 1),('最大建议 epoch', 'min_epochs+patience*3', '', 0)],'formula':' patience 决定模型在验证指标不改善时继续等待的 epoch 数','note':'patience 过大浪费算力，过小可能早停。','viz':('bar',0,200)})
add({'ind':'ai','cat':'dev','title':'模型 flops 估算','icon':'⚡','bg':'#ede9fe','desc':'估算全连接层和卷积层的前向 FLOPs。','inputs':[('h','输入高',224,'1'),('w','输入宽',224,'1'),('cin','输入通道',3,'1'),('cout','输出通道',64,'1'),('k','卷积核',3,'1'),('fc_in','全连接输入',1024,'1'),('fc_out','全连接输出',10,'1')],'results':[('卷积 FLOPs', '2*h*w*cin*cout*k*k', '', 0),('全连接 FLOPs', '2*fc_in*fc_out', '', 0),('总 FLOPs', '2*h*w*cin*cout*k*k+2*fc_in*fc_out', '', 0),('MACs（约）', '(2*h*w*cin*cout*k*k+2*fc_in*fc_out)/2', '', 0)],'formula':'卷积 FLOPs ≈ 2 × H × W × C_in × C_out × K²<br>全连接 FLOPs ≈ 2 × in × out','note':'FLOPs 衡量模型计算量。','viz':('bar',0,1000000000)})
add({'ind':'ai','cat':'dev','title':'词嵌入余弦检索','icon':'🔎','bg':'#ede9fe','desc':'计算查询向量与文档向量的余弦相似度排序。','inputs':[('q1','查询 q1',1,'any'),('q2','查询 q2',0,'any'),('d1','文档 d1',0.8,'any'),('d2','文档 d2',0.6,'any')],'results':[('点积', 'q1*d1+q2*d2', '', 4),('查询模', 'Math.sqrt(q1*q1+q2*q2)', '', 4),('文档模', 'Math.sqrt(d1*d1+d2*d2)', '', 4),('余弦相似度', '(q1*d1+q2*d2)/(Math.sqrt(q1*q1+q2*q2)*Math.sqrt(d1*d1+d2*d2))||0', '', 4)],'formula':'cosθ = (q·d) / (|q||d|)','note':'RAG 检索中常用余弦相似度。','viz':('gauge',-1,1)})
add({'ind':'ai','cat':'dev','title':'温度缩放 Softmax','icon':'🌡️','bg':'#ede9fe','desc':'观察温度参数对 Softmax 分布尖锐程度的影响。','inputs':[('z1','Logit 1',2,'any'),('z2','Logit 2',1,'any'),('z3','Logit 3',0.5,'any'),('t','温度 T',1,'any')],'results':[('T=1 P1', 'Math.exp(z1)/(Math.exp(z1)+Math.exp(z2)+Math.exp(z3))*100', '%', 2),('低温 P1', 'Math.exp(z1/t)/(Math.exp(z1/t)+Math.exp(z2/t)+Math.exp(z3/t))*100', '%', 2),('高温 P1', 'Math.exp(z1/(t*2))/(Math.exp(z1/(t*2))+Math.exp(z2/(t*2))+Math.exp(z3/(t*2)))*100', '%', 2),('分布熵','-Math.exp(z1/t)/(Math.exp(z1/t)+Math.exp(z2/t)+Math.exp(z3/t))*Math.log(Math.exp(z1/t)/(Math.exp(z1/t)+Math.exp(z2/t)+Math.exp(z3/t)))-Math.exp(z2/t)/(Math.exp(z1/t)+Math.exp(z2/t)+Math.exp(z3/t))*Math.log(Math.exp(z2/t)/(Math.exp(z1/t)+Math.exp(z2/t)+Math.exp(z3/t)))-Math.exp(z3/t)/(Math.exp(z1/t)+Math.exp(z2/t)+Math.exp(z3/t))*Math.log(Math.exp(z3/t)/(Math.exp(z1/t)+Math.exp(z2/t)+Math.exp(z3/t)))','',4)],'formula':'Pᵢ = e^(zᵢ/T) / Σe^(zⱼ/T)<br>T→0 更尖锐，T→∞ 更均匀','note':'知识蒸馏中常用温度缩放。','viz':('bar',0,100)})
add({'ind':'ai','cat':'dev','title':'贝叶斯后验概率','icon':'🎲','bg':'#ede9fe','desc':'根据先验概率和似然计算后验概率。','inputs':[('prior','先验 P(A)',0.01,'any'),('sens','似然 P(B|A)',0.95,'any'),('spec','特异度 P(¬B|¬A)',0.95,'any')],'results':[('P(B)', 'prior*sens+(1-prior)*(1-spec)', '', 6),('后验 P(A|B)', '(prior*sens)/(prior*sens+(1-prior)*(1-spec))*100', '%', 4),('阳性预测值', '(prior*sens)/(prior*sens+(1-prior)*(1-spec))*100', '%', 2),('阴性预测值', '((1-prior)*spec)/((1-prior)*spec+prior*(1-sens))*100', '%', 2)],'formula':'P(A|B) = P(B|A)·P(A) / P(B)<br>P(B) = P(B|A)P(A) + P(B|¬A)P(¬A)','note':'即使灵敏度和特异度都很高，低先验也会使后验较低。','viz':('bar',0,100)})
add({'ind':'ai','cat':'dev','title':'L1 L2 正则化惩罚','icon':'🔧','bg':'#ede9fe','desc':'计算 L1 和 L2 正则化对损失的惩罚项。','inputs':[('w1','权重1',0.5,'any'),('w2','权重2',-0.3,'any'),('w3','权重3',0.2,'any'),('lambda_l1','L1 系数',0.01,'any'),('lambda_l2','L2 系数',0.01,'any')],'results':[('L1 惩罚', 'lambda_l1*(Math.abs(w1)+Math.abs(w2)+Math.abs(w3))', '', 6),('L2 惩罚', 'lambda_l2*(w1*w1+w2*w2+w3*w3)', '', 6),('总惩罚', 'lambda_l1*(Math.abs(w1)+Math.abs(w2)+Math.abs(w3))+lambda_l2*(w1*w1+w2*w2+w3*w3)', '', 6)],'formula':'L1 = λ₁Σ|w|<br>L2 = λ₂Σw²','note':'L1 产生稀疏权重，L2 使权重平滑。','viz':('bar',0,1)})
